// @ts-check
/** DNS-pinned, cookie-free selected-image fetch for one-shot browser asks. */

import dns from 'dns';
import http from 'http';
import https from 'https';
import net from 'net';
import { isBlockedIP } from './url-guard.mjs';

const MAX_IMAGE_BYTES = 1_200_000;
const MAX_REDIRECTS = 2;
const TIMEOUT_MS = 15_000;

function isUnsafeAddress(address) {
  if (isBlockedIP(address)) return true;
  if (!net.isIPv6(address)) return false;
  const value = address.toLowerCase();
  // Cover compressed IPv4-mapped literals and the full fe80::/10 range.
  if (value.startsWith('::')) return true;
  const firstHextet = Number.parseInt(value.split(':', 1)[0] || '0', 16);
  return Number.isFinite(firstHextet) && (firstHextet & 0xffc0) === 0xfe80;
}

function pinnedLookup(hostname, options, callback) {
  dns.lookup(hostname, { all: true }, (error, addresses) => {
    if (error) { callback(error); return; }
    if (!addresses?.length || addresses.some(row => isUnsafeAddress(row.address))) {
      callback(new Error('selected image host resolves to a private or unsafe address'));
      return;
    }
    const chosen = addresses[0];
    if (options?.all) callback(null, [chosen]);
    else callback(null, chosen.address, chosen.family);
  });
}

function validateUrl(value, { requireHttps = false } = {}) {
  let url;
  try { url = new URL(String(value || '')); }
  catch { throw new Error('selected image URL is invalid'); }
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) {
    throw new Error('selected image URL is not allowed');
  }
  if (requireHttps && url.protocol !== 'https:') {
    throw new Error('selected image URL must use HTTPS');
  }
  // Node may bypass a custom lookup callback for literal IPs, so validate the
  // literal before request construction as well as checking every DNS answer.
  const hostname = url.hostname.replace(/^\[|\]$/g, '');
  if (net.isIP(hostname) && isUnsafeAddress(hostname)) {
    throw new Error('selected image URL points to a private or unsafe address');
  }
  return url;
}

/** @param {URL} url @param {any} [deps] */
function requestOnce(url, {
  requestHttp = http.request,
  requestHttps = https.request,
  accept = '*/*',
  signal = null,
} = {}) {
  return new Promise((resolve, reject) => {
    const timeoutSignal = AbortSignal.timeout(TIMEOUT_MS);
    const requestSignal = signal ? AbortSignal.any([signal, timeoutSignal]) : timeoutSignal;
    const request = (url.protocol === 'https:' ? requestHttps : requestHttp)({
      protocol: url.protocol,
      hostname: url.hostname,
      port: url.port || undefined,
      path: `${url.pathname}${url.search}`,
      method: 'GET',
      headers: {
        Accept: accept,
        'User-Agent': 'OpenEnsemble-Bridge/1.0',
      },
      lookup: pinnedLookup,
      timeout: TIMEOUT_MS,
      signal: requestSignal,
    }, response => resolve(response));
    request.on('timeout', () => request.destroy(new Error('selected image request timed out')));
    request.on('error', reject);
    request.end();
  });
}

/**
 * @param {unknown} rawUrl
 * @param {{maxBytes:number,mimePattern:RegExp,label:string,accept?:string,requireHttps?:boolean,signal?:AbortSignal|null}} policy
 * @param {any} [deps]
 */
export async function fetchBrowserPublicResource(rawUrl, policy, deps = {}) {
  const maxBytes = Math.max(1, Number(policy?.maxBytes) || 0);
  const label = String(policy?.label || 'resource');
  if (!(policy?.mimePattern instanceof RegExp)) throw new Error('resource MIME policy is required');
  const urlPolicy = { requireHttps: policy?.requireHttps === true };
  let url = validateUrl(rawUrl, urlPolicy);
  for (let redirect = 0; redirect <= MAX_REDIRECTS; redirect++) {
    const response = await requestOnce(url, {
      ...deps,
      accept: policy.accept || '*/*',
      signal: policy.signal ?? deps.signal ?? null,
    });
    const status = Number(response.statusCode || 0);
    if (status >= 300 && status < 400 && response.headers.location) {
      response.resume();
      if (redirect === MAX_REDIRECTS) throw new Error(`${label} redirected too many times`);
      url = validateUrl(new URL(response.headers.location, url).href, urlPolicy);
      continue;
    }
    if (status !== 200) {
      response.resume();
      throw new Error(`${label} fetch failed (${status || 'unknown status'})`);
    }
    const mimeType = String(response.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
    if (!policy.mimePattern.test(mimeType)) {
      response.resume();
      throw new Error(`selected URL did not return a supported ${label}`);
    }
    const declared = Number(response.headers['content-length'] || 0);
    if (declared > maxBytes) {
      response.resume();
      throw new Error(`${label} is too large`);
    }
    const chunks = [];
    let size = 0;
    for await (const chunk of response) {
      size += chunk.length;
      if (size > maxBytes) {
        response.destroy();
        throw new Error(`${label} is too large`);
      }
      chunks.push(chunk);
    }
    const bytes = Buffer.concat(chunks);
    if (!bytes.length) throw new Error(`${label} was empty`);
    return {
      name: url.pathname.split('/').filter(Boolean).at(-1)?.slice(0, 100) || `selected-${label}`,
      mimeType,
      bytes,
      sourceUrl: `${url.origin}${url.pathname}`,
    };
  }
  throw new Error(`${label} fetch failed`);
}

export async function fetchBrowserSelectedImage(rawUrl, deps = {}) {
  const result = await fetchBrowserPublicResource(rawUrl, {
    maxBytes: MAX_IMAGE_BYTES,
    mimePattern: /^image\/(?:png|jpe?g|webp|gif)$/,
    label: 'selected image',
    accept: 'image/png,image/jpeg,image/webp,image/gif',
  }, deps);
  return { ...result, base64: result.bytes.toString('base64'), bytes: undefined };
}

export const BROWSER_IMAGE_LIMITS = Object.freeze({ maxBytes: MAX_IMAGE_BYTES, maxRedirects: MAX_REDIRECTS });
export const __test = Object.freeze({ validateUrl, pinnedLookup, isUnsafeAddress });

// @ts-check
/**
 * MCP client — connection pool + tool dispatch.
 *
 * Multi-user shape:
 *   - One process per (userId, serverId) pair. Credentials live in each
 *     user's stdio process env, never shared with another user's process.
 *     A misbehaving server can't see another user's tokens because it can't
 *     see another user's process.
 *   - Lazily spawned on first call. An idle timer shuts the process down
 *     after IDLE_MS of no use to reclaim memory; the next call respawns.
 *   - Crash recovery: if the process exits unexpectedly, the pool entry is
 *     cleared. The next caller respawns transparently.
 *
 * Transports supported here:
 *   - stdio (phase 1) — spawn a subprocess, talk JSON-RPC over its
 *     stdin/stdout. Most reference MCP servers ship as stdio.
 *
 * Transports for later phases:
 *   - http / sse — remote MCP servers reachable over the network. The
 *     SDK supports it; we just need to plumb it through getOrCreateClient.
 *
 * NOT handled here (lives in skills/mcp/execute.mjs):
 *   - Mapping from `mcp_<server>_<tool>` namespaced tool name back to the
 *     bare tool name the server expects. The dispatcher splits the prefix
 *     and passes the bare name to callTool.
 */
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';

const IDLE_MS = 5 * 60 * 1000;  // 5 min — close idle servers
// 60s handshake to cover `npx -y` package downloads on first run. The
// previous 15s was tight enough that any first-time install (which downloads
// ~30-100 MB of node_modules for some servers) would spuriously fail the
// warmup. Subsequent calls use the cached npm cache and are nearly instant.
const HANDSHAKE_TIMEOUT_MS = 60 * 1000;

/** @type {Map<string, ConnectionEntry>} */
const _pool = new Map();

/**
 * Per-server connection status, separate from the pool entry so it survives
 * idle-eviction and gives the Settings UI something to render even when no
 * connection is currently held.
 *
 * @typedef {Object} ServerStatus
 * @property {'connecting'|'ready'|'error'|'idle'|'unknown'} state
 * @property {string|null} lastError
 * @property {number|null} lastConnectedAt   epoch ms of last successful connect
 * @property {number|null} toolCount         tool count from last successful listTools
 *
 * @type {Map<string, ServerStatus>}
 */
const _status = new Map();

function setStatus(ownerId, serverId, patch) {
  const key = poolKey(ownerId, serverId);
  const prev = _status.get(key) ?? { state: 'unknown', lastError: null, lastConnectedAt: null, toolCount: null };
  _status.set(key, { ...prev, ...patch });
}

/** Read the cached status for one server. Keyed by user (each user has
 * their own server processes — no sharing). */
export function getServerStatus(ownerId, serverId) {
  return _status.get(poolKey(ownerId, serverId))
    ?? { state: 'unknown', lastError: null, lastConnectedAt: null, toolCount: null };
}

/**
 * @typedef {Object} ServerConfig
 * @property {string} id              short unique id within the user's mcp.json
 * @property {'stdio'|'http'} transport
 * @property {string} [command]       stdio: program to spawn (e.g. "npx")
 * @property {string[]} [args]        stdio: args
 * @property {Record<string,string>} [env]  stdio: env passed to the subprocess
 * @property {string} [url]           http (later)
 * @property {string} [displayName]
 */

/**
 * @typedef {Object} ConnectionEntry
 * @property {import('@modelcontextprotocol/sdk/client/index.js').Client} client
 * @property {import('@modelcontextprotocol/sdk/client/stdio.js').StdioClientTransport
 *           | import('@modelcontextprotocol/sdk/client/streamableHttp.js').StreamableHTTPClientTransport} transport
 * @property {NodeJS.Timeout|null} idleTimer
 * @property {any[]|null} toolsCache
 * @property {number} lastUsed
 */

function poolKey(ownerId, serverId) {
  return `${ownerId}::${serverId}`;
}

async function spawnClient(ownerId, cfg) {
  let transport;
  if (cfg.transport === 'stdio' || !cfg.transport) {
    if (!cfg.command) throw new Error('stdio MCP server config missing `command`');
    transport = new StdioClientTransport({
      command: cfg.command,
      args: cfg.args ?? [],
      env: { ...process.env, ...(cfg.env ?? {}) },
    });
  } else if (cfg.transport === 'http') {
    if (!cfg.url) throw new Error('http MCP server config missing `url`');
    // headers may include auth (Authorization: Bearer ...), API keys, or
    // custom values per server. Stored encrypted in users/<id>/mcp.json.
    const headers = (cfg.headers && typeof cfg.headers === 'object') ? { ...cfg.headers } : {};
    const opts = { requestInit: { headers } };
    // OAuth: when the server config asks for it, hand the SDK an
    // OAuthClientProvider keyed on the OWNER (whose tokens we read/write).
    // The SDK injects Bearer <access_token>, handles 401 → refresh, and
    // on a full re-auth need will call provider.redirectToAuthorization()
    // — but at runtime that's a dead-end (the user isn't here). The
    // /api/mcp/servers/:id/oauth/start route is the only entry point that
    // expects redirectToAuthorization to fire.
    if (cfg.auth === 'oauth') {
      const { OeOAuthProvider } = await import('./mcp-oauth.mjs');
      opts.authProvider = new OeOAuthProvider({
        ownerUserId: ownerId,
        serverId: cfg.id,
        redirectOrigin: cfg.oauthRedirectOrigin || '',
        scope: cfg.oauthScope || '',
      });
    }
    transport = new StreamableHTTPClientTransport(new URL(cfg.url), opts);
  } else {
    throw new Error(`MCP transport "${cfg.transport}" not recognized — use "stdio" or "http"`);
  }
  const client = new Client(
    { name: 'openensemble', version: '1.0.0' },
    { capabilities: {} },
  );
  // Race connect against a timeout. A misconfigured server (wrong command,
  // unreachable URL, slow npx download) otherwise hangs forever.
  let timer = null;
  // Hold the connect promise and pre-attach a catch: after a timeout wins the
  // race, the losing connect() may still reject later — unobserved, that's an
  // unhandledRejection.
  const connectP = client.connect(transport);
  connectP.catch(() => {});
  try {
    await Promise.race([
      connectP,
      new Promise((_, reject) => { timer = setTimeout(
        () => reject(new Error(`MCP server "${cfg.id}" handshake timed out after ${HANDSHAKE_TIMEOUT_MS}ms`)),
        HANDSHAKE_TIMEOUT_MS,
      ); }),
    ]);
  } catch (e) {
    // Reap the spawned subprocess/socket — the npx child (possibly mid-
    // download) used to keep running orphaned after a handshake timeout.
    try { await transport.close?.(); } catch { /* best effort */ }
    try { await client.close?.(); } catch { /* best effort */ }
    throw e;
  } finally {
    clearTimeout(timer);
  }
  return { client, transport };
}

// In-flight connects keyed like _pool — two concurrent first calls used to
// spawn two subprocesses (the second orphaning the first's pool entry).
const _pendingConnects = new Map();

async function getOrCreateEntry(ownerId, cfg) {
  const key = poolKey(ownerId, cfg.id);
  const existing = _pool.get(key);
  if (existing) {
    bumpIdle(existing);
    return existing;
  }
  const pending = _pendingConnects.get(key);
  if (pending) return pending;
  const p = _createEntry(ownerId, cfg, key).finally(() => _pendingConnects.delete(key));
  _pendingConnects.set(key, p);
  return p;
}

async function _createEntry(ownerId, cfg, key) {
  setStatus(ownerId, cfg.id, { state: 'connecting', lastError: null });
  let client, transport;
  try {
    ({ client, transport } = await spawnClient(ownerId, cfg));
  } catch (e) {
    setStatus(ownerId, cfg.id, { state: 'error', lastError: e.message });
    throw e;
  }
  setStatus(ownerId, cfg.id, { state: 'ready', lastConnectedAt: Date.now(), lastError: null });
  /** @type {ConnectionEntry} */
  const entry = {
    client, transport, idleTimer: null, toolsCache: null,
    lastUsed: Date.now(),
  };
  bumpIdle(entry);
  _pool.set(key, entry);
  transport.onclose = () => {
    const cur = _pool.get(key);
    if (cur === entry) {
      if (cur.idleTimer) clearTimeout(cur.idleTimer);
      _pool.delete(key);
      setStatus(ownerId, cfg.id, { state: 'idle' });
    }
  };
  return entry;
}

function bumpIdle(entry) {
  entry.lastUsed = Date.now();
  if (entry.idleTimer) clearTimeout(entry.idleTimer);
  entry.idleTimer = setTimeout(async () => {
    try { await entry.client.close(); } catch {}
  }, IDLE_MS);
}

/**
 * List tools exposed by the server, cached for the lifetime of this
 * connection. Invalidate by closing the connection (which the idle timer
 * does automatically).
 *
 * @returns {Promise<Array<{name: string, description?: string, inputSchema?: any}>>}
 */
export async function listTools(ownerId, cfg) {
  const entry = await getOrCreateEntry(ownerId, cfg);
  if (entry.toolsCache) return entry.toolsCache;
  try {
    const res = await entry.client.listTools();
    entry.toolsCache = res.tools ?? [];
    setStatus(ownerId, cfg.id, { state: 'ready', toolCount: entry.toolsCache.length });
    return entry.toolsCache;
  } catch (e) {
    setStatus(ownerId, cfg.id, { state: 'error', lastError: e.message });
    throw e;
  }
}

/**
 * Invoke an MCP tool. The bare `toolName` is the name the server knows —
 * call sites that have the namespaced `mcp_<server>_<tool>` name must strip
 * the prefix before calling this.
 *
 * @returns {Promise<any>}
 */
export async function callTool(ownerId, cfg, toolName, args, { signal = null } = {}) {
  const entry = await getOrCreateEntry(ownerId, cfg);
  try {
    const result = await entry.client.callTool(
      { name: toolName, arguments: args },
      undefined,
      signal ? { signal } : undefined,
    );
    setStatus(ownerId, cfg.id, { state: 'ready' });
    return result;
  } catch (e) {
    if (signal?.aborted || e?.name === 'AbortError') throw e;
    setStatus(ownerId, cfg.id, { state: 'error', lastError: e.message });
    throw e;
  }
}

/**
 * Tear down all pooled connections — call on server shutdown so subprocesses
 * don't linger.
 */
export async function shutdownAll() {
  for (const [, entry] of _pool) {
    if (entry.idleTimer) clearTimeout(entry.idleTimer);
    try { await entry.client.close(); } catch {}
  }
  _pool.clear();
}

/**
 * Close one (user, server) connection so the next call respawns fresh.
 * Used by the per-server Reconnect button. Status flips to 'idle' via
 * the transport.onclose hook, then back to 'connecting'/'ready' when the
 * next listTools/callTool fires. Safe to call when no entry exists —
 * just a no-op.
 */
export async function disconnect(ownerId, serverId) {
  const key = poolKey(ownerId, serverId);
  const entry = _pool.get(key);
  if (!entry) return;
  if (entry.idleTimer) clearTimeout(entry.idleTimer);
  try { await entry.client.close(); } catch {}
  _pool.delete(key);
}

/** Debugging surface — currently-live pool entries. */
export function poolStats() {
  const now = Date.now();
  return Array.from(_pool.entries()).map(([k, v]) => ({
    key: k,
    idleMs: now - v.lastUsed,
    toolsCached: v.toolsCache?.length ?? 0,
  }));
}

/**
 * Roster-aware request_tools schema policy.
 *
 * The coordinator manifest describes normal multi-agent OE behavior. A
 * singleton roster has no valid named agent to delegate to, so its effective
 * runtime schema replaces ask_agent guidance with task-scoped worker guidance.
 * Keep that transformation here so runtime resolution and lab attestation use
 * the same canonical definition.
 */

export const SINGLETON_REQUEST_TOOLS_DESCRIPTION = 'Expand your own tool surface mid-turn. Your initial list was trimmed, but the server retains your full permission-scoped surface. If a needed tool is absent, call request_tools and continue the task yourself. Use spawn_worker only when the user explicitly requests background or agent execution; a long task alone is not authorization. Scheduled tasks already run in the background and should complete directly unless their task explicitly requests workers. The cost is one extra model round-trip, so call only when the needed tool is missing.';

export function applyRequestToolsRosterPolicy(tool, { rosterSolo = false } = {}) {
  if (!rosterSolo || tool?.function?.name !== 'request_tools') return tool;
  return {
    ...tool,
    function: {
      ...tool.function,
      description: SINGLETON_REQUEST_TOOLS_DESCRIPTION,
    },
  };
}

/**
 * Embedding-based specialist router.
 *
 * Companion to the regex-based router in chat-dispatch.mjs. When regex misses,
 * we embed the user's message with the bundled nomic-embed model (~70MB, ~20ms
 * per query in-process) and find the nearest example phrase across all
 * specialist skills. If the match is confident and unambiguous, we route the
 * turn straight to that skill's owner — skipping the coordinator's reasoning entirely.
 *
 * Manifest field: each service skill can declare `intent_examples` — an array
 * of natural-language phrases that represent typical user requests for that
 * skill. Boot-time we embed every example once; per-turn we embed the user's
 * message and dot-product against all examples (already normalized, so dot =
 * cosine similarity).
 *
 * Tunables:
 *   - threshold: minimum cosine sim for a confident match. Default 0.72.
 *     Toggleable at runtime via /threshold N (in chat-dispatch).
 *   - gap: minimum margin between best and second-best skill. If two skills
 *     score within `gap` of each other, treat as ambiguous → fall through.
 *     Default 0.05.
 *
 * Returns null on:
 *   - cache not loaded
 *   - user not on coordinator
 *   - no example exceeds threshold
 *   - best skill within `gap` of second-best (ambiguous)
 */

import { embed } from '../memory/embedding.mjs';
import { listRoles, listAllRoles, getRoleAssignments } from '../roles.mjs';
import { stableAgentRef } from './agent-ref.mjs';

let _examples = []; // [{ skillId, name, phrase, vec }]
let _loaded = false;
let _vectorDimension = null;
// 0.78 default chosen empirically: catches most paraphrases (sim 0.80-0.95 for
// real intents) while keeping false positives like "what time is it" → gcal
// (sim 0.777) below threshold. Tune live via /threshold in chat.
let _threshold = 0.78;
const DEFAULT_GAP = 0.05;

function validateVector(vec, expectedDimension = null) {
  if (!Array.isArray(vec) || vec.length === 0) return { ok: false, reason: 'empty' };
  if (expectedDimension != null && vec.length !== expectedDimension) {
    return { ok: false, reason: 'dimension' };
  }
  let normSquared = 0;
  for (const value of vec) {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      return { ok: false, reason: 'malformed' };
    }
    normSquared += value * value;
    if (!Number.isFinite(normSquared)) return { ok: false, reason: 'malformed' };
  }
  if (!(normSquared > 0)) return { ok: false, reason: 'zero' };
  return { ok: true };
}

export async function loadIntentEmbeddings() {
  _loaded = false;
  const next = [];
  let skillCount = 0;
  const start = Date.now();
  // listAllRoles() (not listRoles()) so per-user custom skills with
  // intent_examples also get indexed. Each example is tagged with the owning
  // userId derived from manifest.createdBy (or null for global system skills),
  // and classifyByEmbedding filters out cross-user examples at query time so
  // user A's custom-skill phrases never match user B's prompts.
  const refused = { empty: 0, malformed: 0, zero: 0, dimension: 0 };
  let vectorDimension = null;
  for (const m of listAllRoles()) {
    if (!Array.isArray(m.intent_examples) || m.intent_examples.length === 0) continue;
    const ownerUserId = typeof m.createdBy === 'string' ? m.createdBy : null;
    skillCount++;
    for (const phrase of m.intent_examples) {
      if (typeof phrase !== 'string' || !phrase.trim()) continue;
      try {
        const vec = await embed(phrase);
        // embed() converts provider failures into zero vectors so callers do
        // not crash. Such vectors can never match a query, though, and storing
        // them makes a dead embedding provider look like a healthy loaded
        // index. Refuse and count them so the failure is operationally loud.
        const validation = validateVector(vec, vectorDimension);
        if (!validation.ok) {
          refused[validation.reason]++;
          continue;
        }
        if (vectorDimension == null) vectorDimension = vec.length;
        next.push({ skillId: m.id, name: m.name, phrase, vec, ownerUserId });
      } catch (e) {
        console.warn(`[embed-router] failed to embed example "${phrase}" for ${m.id}:`, e.message);
      }
    }
  }
  _examples = next;
  _vectorDimension = vectorDimension;
  _loaded = true;
  console.log(`[embed-router] loaded ${_examples.length} examples across ${skillCount} skills in ${Date.now() - start}ms`);
  const refusedTotal = Object.values(refused).reduce((sum, count) => sum + count, 0);
  if (refusedTotal > 0) {
    console.error(`[embed-router] REFUSED ${refusedTotal} invalid embedding examples (zero-norm=${refused.zero}, empty/non-array=${refused.empty}, non-numeric/non-finite=${refused.malformed}, dimension-mismatch=${refused.dimension}); embedding-based intent matching is degraded until the index is rebuilt with healthy vectors`);
  }
}

// Force a rebuild — call after a skill is added/removed/edited so new examples
// take effect without a server restart.
export function invalidateIntentEmbeddings() {
  _loaded = false;
  _examples = [];
  _vectorDimension = null;
}

export function getEmbedThreshold() { return _threshold; }
export function setEmbedThreshold(t) {
  const n = Number(t);
  if (!Number.isFinite(n) || n < 0 || n > 1) return false;
  _threshold = n;
  return true;
}

// Vectors come back from nomic-embed normalized (see memory/builtin-embed.mjs
// `normalize: true`), so dot product equals cosine similarity. No /(|a||b|).
function dot(a, b) {
  let s = 0;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) s += a[i] * b[i];
  return s;
}

/**
 * Classify a user message against the loaded intent examples.
 * Returns { skillId, agentId, name, sim, phrase, strategy } or null.
 *
 * Only fires when:
 *   - currentAgentId matches the user's coordinator (don't surprise users in
 *     specialist chats)
 *   - exactly one skill clearly wins (sim ≥ threshold, gap to next ≥ gap)
 *   - that skill is assigned to a non-coordinator agent
 */
async function rankIntentSkillsByEmbedding(text, userId, currentAgentId, opts = {}) {
  if (!_loaded || _examples.length === 0) return null;
  if (typeof text !== 'string' || text.trim().length < 4) return null;

  const assignments = getRoleAssignments(userId);
  const coordAgentId = assignments?.coordinator;
  // currentAgentId guard: when set, must match the user's coordinator.
  // The tool-router calls with currentAgentId=null to mean "I am the
  // coordinator's pre-LLM trim — don't gate on the chat's agent."
  if (currentAgentId != null && (!coordAgentId || stableAgentRef(userId, currentAgentId) !== coordAgentId)) return null;

  // includeUnassigned: tool-router passes true so non-service skills like
  // `profiles` (which have no agent owner) can also win. Specialist-router
  // calls without it — for routing-to-a-specialist we need a real owner.
  const includeUnassigned = opts.includeUnassigned === true;
  const allowedSkillIds = opts.allowedSkillIds instanceof Set ? opts.allowedSkillIds : null;

  let queryVec;
  try { queryVec = await embed(text); }
  catch (e) { console.warn('[embed-router] query embed failed:', e.message); return null; }
  if (!validateVector(queryVec, _vectorDimension).ok) return null;

  // Best example per skill, ignoring skills not assigned (or owned by coord).
  // The literal "coordinator" string is an alias — resolve it first.
  //
  // For specialist routing (includeUnassigned=false), skills owned by the
  // coordinator are skipped — you don't delegate from yourself to yourself.
  // For TOOL routing (includeUnassigned=true), the opposite: a coordinator
  // holding e.g. oe-admin should match admin queries so the tool-router can
  // include the role's tools on this turn. Without this branch, oe-admin
  // examples were silently filtered out — every admin query missed the
  // classifier even with perfect-match examples in the manifest.
  const bestPerSkill = new Map();
  for (const ex of _examples) {
    // Per-user scoping: examples from user A's custom skills must NOT match
    // user B's prompts. ownerUserId === null means a global system skill,
    // which is shared by everyone.
    if (ex.ownerUserId && ex.ownerUserId !== userId) continue;
    if (allowedSkillIds && !allowedSkillIds.has(ex.skillId)) continue;
    const rawOwner = assignments[ex.skillId];
    let owner = null;
    if (rawOwner) {
      owner = rawOwner === 'coordinator' ? coordAgentId : rawOwner;
      if (owner === coordAgentId && !includeUnassigned) continue;
    } else if (!includeUnassigned || ex.ownerUserId) {
      // Built-in unassigned skills may participate in coordinator tool
      // routing. A user-created skill with no assignment means exactly what
      // Settings says: no agent can use it, including via dynamic expansion.
      continue;
    }
    const sim = dot(queryVec, ex.vec);
    if (!Number.isFinite(sim)) continue;
    const cur = bestPerSkill.get(ex.skillId);
    if (!cur || sim > cur.sim) {
      bestPerSkill.set(ex.skillId, { sim, agentId: owner, name: ex.name, phrase: ex.phrase });
    }
  }
  if (bestPerSkill.size === 0) return [];

  // Rank skills by their best example similarity.
  const ranked = [...bestPerSkill.entries()]
    .map(([skillId, b]) => ({ skillId, ...b }))
    .sort((a, b) => b.sim - a.sim);
  return ranked.map(hit => ({ ...hit, strategy: 'embed' }));
}

/**
 * Return the best embedding hit per skill, sorted by similarity. This is a
 * diagnostic/building-block API; callers still choose their own threshold,
 * ambiguity band, and maximum candidate count.
 */
export async function rankByEmbedding(text, userId, currentAgentId, opts = {}) {
  return await rankIntentSkillsByEmbedding(text, userId, currentAgentId, opts) ?? [];
}

/**
 * Classify one unambiguous winner. Preserves the specialist-router contract;
 * the coordinator tool router may use rankByEmbedding for bounded ambiguity
 * expansion without weakening this stricter delegation path.
 */
export async function classifyByEmbedding(text, userId, currentAgentId, opts = {}) {
  const ranked = await rankIntentSkillsByEmbedding(text, userId, currentAgentId, opts);
  if (!ranked?.length) return null;
  const threshold = typeof opts.threshold === 'number' ? opts.threshold : _threshold;
  const gap = typeof opts.gap === 'number' ? opts.gap : DEFAULT_GAP;
  const top = ranked[0];
  if (top.sim < threshold) return null;

  // Disambiguation: if the next-best skill is within `gap`, it's a tie — fall
  // through so the LLM can clarify rather than guess wrong.
  const second = ranked[1];
  if (second && (top.sim - second.sim) < gap) return null;

  return top;
}

/**
 * Security policy applied before loading Transformers.js.
 *
 * OpenEnsemble currently uses Transformers.js for text-only pipelines, but
 * Transformers.js also loads sharp's image helpers. Keep the vulnerable
 * libvips decoders unavailable even though those image paths are not used.
 */

export const BLOCKED_SHARP_LOADERS = Object.freeze([
  'VipsForeignLoadNsgif',
  'VipsForeignLoadTiff',
  'VipsForeignLoadVips',
]);

let sharpPolicyPromise = null;

function warningFor(error) {
  const detail = error instanceof Error ? error.message : String(error);
  return `[security] Could not apply the sharp decoder policy (${detail}); continuing with text-only Transformers.`;
}

/**
 * Apply sharp's official per-operation block policy.
 *
 * This helper is deliberately non-throwing. A missing native sharp build or
 * an older sharp API must not disable OpenEnsemble's text embedding path.
 */
export function applySharpDecoderPolicy(sharp, { warn = console.warn } = {}) {
  try {
    if (typeof sharp?.block !== 'function') {
      throw new Error('sharp.block is unavailable');
    }
    sharp.block({ operation: [...BLOCKED_SHARP_LOADERS] });
    return true;
  } catch (error) {
    warn(warningFor(error));
    return false;
  }
}

/** Apply the process-wide policy once, including across concurrent callers. */
export function ensureTransformersRuntimePolicy() {
  if (!sharpPolicyPromise) {
    sharpPolicyPromise = (async () => {
      try {
        const sharpModule = await import('sharp');
        return applySharpDecoderPolicy(sharpModule.default ?? sharpModule);
      } catch (error) {
        console.warn(warningFor(error));
        return false;
      }
    })();
  }
  return sharpPolicyPromise;
}

/** Load Transformers.js only after the sharp policy has settled. */
export async function loadTransformers() {
  await ensureTransformersRuntimePolicy();
  return import('@huggingface/transformers');
}

// @ts-check
/**
 * Memory contract for detached task-scoped workers.
 *
 * Workers inherit the owner's already permission-filtered persona, child
 * safety text, tool schemas, and standing per-skill role rules in their cloned
 * agent record. Cortex contributes only query-relevant standing context from
 * that same stable owner: params/rules, scoped user facts, and governed
 * confirmed global preferences/constraints. Episodes are always excluded.
 * chat.mjs separately keeps ordinary session history, trigger nudges,
 * cross-agent reads, and every memory write disabled for ephemeral workers.
 */

/**
 * Validate the only ephemeral shape allowed to request owner memory.
 * Requiring an explicit owner marker on the clone prevents a generic
 * ephemeral caller from using turnOpts as an owned-agent memory oracle.
 */
export function workerStandingMemoryOwner(agent, turnOpts = {}) {
  const requested = typeof turnOpts?.workerMemoryAgentId === 'string'
    ? turnOpts.workerMemoryAgentId.trim()
    : '';
  if (!requested || agent?.ephemeral !== true || turnOpts?.isolatedTaskRun !== true) return null;
  if (typeof agent?.workerOwnerId !== 'string' || agent.workerOwnerId !== requested) return null;
  return requested;
}

// A detached worker may perform the task's ordinary domain actions, but it may
// not rewrite the assistant/account that owns it or create more autonomous
// work. Keep this list explicit: these are OE control-plane writes, not a
// heuristic over names such as "create" or "delete" (which would also remove
// legitimate task tools like create_document or email_delete).
//
// Read-only counterparts intentionally remain available (recall_facts,
// skill_list_rules, list_roles, mcp_list_servers, profile_load, etc.), as do
// request_tools and report_progress. chat.mjs filters this set before routing,
// then filters both the routed and recoverable sets again.
