        'X-OE-Bootstrap-Credential': bootstrapCredential,
      },
      body: JSON.stringify({ name, emoji, password: <REDACTED> }),
    });
    const d = await r.json();
    if (!r.ok) { $('setupError').textContent = d.error ?? 'Failed to create profile'; return; }
    // Auto-login
    const lr = await _origFetch('/api/login', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId: d.id, password: <REDACTED> }),
