// Per-role/per-skill execution overrides. These are account-scoped server
// settings; the manifest itself stays immutable. Empty model values mean
// "use the model selected on the agent that is handling this request", while
// explicit `auto` remains a real effort choice rather than being overloaded
// as inheritance. Automatic skill/task policy never swaps a named agent model.
const _SKILL_EXECUTION_EFFORT_OPTIONS = [
  { value: 'auto', label: 'Auto' },
  { value: 'off', label: 'Off' },
  { value: 'on', label: 'On' },
  { value: 'none', label: 'None' },
  { value: 'minimal', label: 'Minimal' },
  { value: 'low', label: 'Low' },
  { value: 'medium', label: 'Medium' },
  { value: 'high', label: 'High' },
  { value: 'xhigh', label: 'Extra High' },
  { value: 'max', label: 'Max' },
  { value: 'ultra', label: 'Ultra' },
];
const _skillExecutionSaved = new Map();
const _skillExecutionEffortRequests = new Map();

function _normalizeSkillExecution(execution) {
  const raw = execution && typeof execution === 'object' ? execution : {};
  const provider = typeof raw.provider === 'string' && raw.provider.trim() ? raw.provider.trim() : null;
  const model = typeof raw.model === 'string' && raw.model.trim() ? raw.model.trim() : null;
  const reasoningEffort = typeof raw.reasoningEffort === 'string' && raw.reasoningEffort.trim()
    ? raw.reasoningEffort.trim().toLowerCase()
    : null;
  return {
    provider: provider && model ? provider : null,
    model: provider && model ? model : null,
    reasoningEffort,
  };
}

function _skillExecutionTextCapableModel(model) {
  if (!model || model.provider === 'fireworks') return false;
  if ((model.provider === 'grok' || model.provider === 'xai')
      && /^grok-imagine-(?:image|video)/i.test(String(model.name || ''))) return false;
  return true;
}

function _skillExecutionModelValue(provider, model) {
  return provider && model ? JSON.stringify([provider, model]) : '';
}

function _parseSkillExecutionModelValue(value) {
  if (!value) return { provider: null, model: null };
  try {
    const pair = JSON.parse(value);
    if (!Array.isArray(pair) || pair.length !== 2
        || typeof pair[0] !== 'string' || !pair[0]
        || typeof pair[1] !== 'string' || !pair[1]) throw new Error('invalid model selection');
    return { provider: pair[0], model: pair[1] };
  } catch {
    return { provider: null, model: null };
  }
}

function _skillExecutionProviderLabel(provider) {
  const labels = {
    anthropic: 'Anthropic', openai: 'OpenAI', 'openai-oauth': 'OpenAI (ChatGPT login)', 'xai-oauth': 'xAI Grok (SuperGrok)',
    gemini: 'Google Gemini', deepseek: 'DeepSeek', mistral: 'Mistral AI', groq: 'Groq',
    together: 'Together AI', perplexity: 'Perplexity', ollama: 'Ollama',
    lmstudio: 'LM Studio', grok: 'xAI Grok', xai: 'xAI Grok',
    openrouter: 'OpenRouter', zai: 'Z.AI',
  };
  if (labels[provider]) return labels[provider];
  const dynamic = typeof window.getCompatProviderMeta === 'function'
    ? window.getCompatProviderMeta().find(p => p.id === provider)
    : null;
  return dynamic?.label || dynamic?.displayName || provider;
}

function _skillExecutionModels() {
  const models = typeof allAvailableModels === 'function' ? allAvailableModels() : [];
  return models.filter(_skillExecutionTextCapableModel);
}

function _skillExecutionModelOptionsHtml(execution) {
  const current = _normalizeSkillExecution(execution);
  const currentValue = _skillExecutionModelValue(current.provider, current.model);
  const groups = new Map();
  let currentAvailable = !currentValue;
  for (const model of _skillExecutionModels()) {
    if (!model?.provider || !model?.name) continue;
    const value = _skillExecutionModelValue(model.provider, model.name);
    if (value === currentValue) currentAvailable = true;
    if (!groups.has(model.provider)) groups.set(model.provider, []);
    groups.get(model.provider).push({ ...model, value });
  }
  let html = `<option value=""${!currentValue ? ' selected' : ''}>Agent model (inherit)</option>`;
  if (currentValue && !currentAvailable) {
    html += `<option value="${escHtml(currentValue)}" selected>${escHtml(current.model)} (unavailable)</option>`;
  }
  for (const [provider, models] of groups) {
    html += `<optgroup label="${escHtml(_skillExecutionProviderLabel(provider))}">`;
    html += models.map(model => `<option value="${escHtml(model.value)}"${model.value === currentValue ? ' selected' : ''}>${escHtml(model.displayName ?? model.name)}</option>`).join('');
    html += '</optgroup>';
  }
  return html;
}

function _skillExecutionEffortOptionsHtml(current, supported = _SKILL_EXECUTION_EFFORT_OPTIONS) {
  const selected = typeof current === 'string' && current ? current : null;
  const seen = new Set();
  const options = [];
  for (const option of Array.isArray(supported) ? supported : []) {
    const value = typeof option?.value === 'string' ? option.value.toLowerCase() : '';
    if (!value || seen.has(value)) continue;
    seen.add(value);
    options.push({ value, label: option.label || value });
  }
  if (selected && !seen.has(selected)) {
    options.push({ value: selected, label: `${selected[0].toUpperCase()}${selected.slice(1)} (not supported for this model)` });
  }
  return `<option value=""${selected ? '' : ' selected'}>Auto (from skill / task)</option>`
    + options.map(option => `<option value="${escHtml(option.value)}"${option.value === selected ? ' selected' : ''}>${escHtml(option.label)}</option>`).join('');
}

function _skillExecutionHintSummary(hint) {
  if (!hint || typeof hint !== 'object') return null;
  const tier = typeof hint.tier === 'string' && hint.tier ? hint.tier : null;
  const effort = typeof hint.effort === 'string' && hint.effort ? hint.effort : null;
  if (!tier && !effort) return null;
  const parts = [];
  if (tier) parts.push(tier[0].toUpperCase() + tier.slice(1));
  if (effort) parts.push(effort[0].toUpperCase() + effort.slice(1));
  return parts.join(' · ');
}

function _skillExecutionSummary(execution, hint = null) {
  const value = _normalizeSkillExecution(execution);
  if (!value.model && !value.reasoningEffort) {
    const auto = _skillExecutionHintSummary(hint);
    return auto ? `Agent model · Auto effort · ${auto}` : 'Agent model · Auto effort';
  }
  const effort = value.reasoningEffort
    ? `${value.reasoningEffort[0].toUpperCase()}${value.reasoningEffort.slice(1)}`
    : 'Agent effort';
  return `Pinned · ${value.model || 'Agent model'} · ${effort}`;
}

function _skillExecutionInheritedAgent(skill, allAgents) {
  const roster = (allAgents ?? []).filter(agent => !agent.archived);
  const assigned = skill.assignment ? roster.find(agent => agent.id === skill.assignment) : null;
  if (assigned) return assigned;
  const inheritedId = typeof skill.inheritedAgentId === 'string' ? skill.inheritedAgentId : null;
  return roster.find(agent => agent.id === inheritedId) || roster[0] || null;
}

function _renderSkillExecutionControls(skill, allAgents) {
  const execution = _normalizeSkillExecution(skill.execution);
  _skillExecutionSaved.set(skill.id, execution);
  const inheritedAgent = _skillExecutionInheritedAgent(skill, allAgents);
  const inheritedModel = _skillExecutionModelValue(inheritedAgent?.provider, inheritedAgent?.model);
  const hint = skill.execution_hint && typeof skill.execution_hint === 'object' ? skill.execution_hint : null;
  const args = escHtml(JSON.stringify([skill.id]));
  const autoLabel = _skillExecutionHintSummary(hint) || 'structure + task shape';
  return `<details class="skill-execution-settings" data-skill-id="${escHtml(skill.id)}" data-inherited-model="${escHtml(inheritedModel)}"
      data-execution-hint="${escHtml(JSON.stringify(hint || {}))}"
      data-toggle-action="refreshSkillExecutionEfforts" data-toggle-args='${args}'>
    <summary class="skill-execution-summary">
      <span>Execution</span>
      <span class="skill-execution-current">${escHtml(_skillExecutionSummary(execution, hint))}</span>
    </summary>
    <div class="skill-execution-body">
      <div class="skill-execution-grid">
        <label>Model
          <select class="skill-execution-model" data-change-action="saveSkillExecution" data-change-args='${args}'>
            ${_skillExecutionModelOptionsHtml(execution)}
          </select>
        </label>
        <label>Reasoning effort
          <select class="skill-execution-effort" data-change-action="saveSkillExecution" data-change-args='${args}'>
            ${_skillExecutionEffortOptionsHtml(execution.reasoningEffort)}
          </select>
        </label>
      </div>
      <div class="skill-execution-hint">Leave Model on <strong>Agent model</strong> to keep the provider/model selected in Settings → Agents (workers included). Automatic skill/task policy may tune reasoning effort using ${escHtml(autoLabel)}, but never swaps a named agent's model. Choose a model here only when you explicitly want this skill to override the agent. Multi-skill turns freeze one profile (strongest explicit pin wins). Local shortcuts may not call a model.</div>
      <div class="skill-execution-status" role="status" aria-live="polite"></div>
    </div>
  </details>`;
}

function _skillExecutionCard(skillId, event) {
  const fromEvent = event?.target?.closest?.('.skill-execution-settings');
  if (fromEvent?.dataset?.skillId === String(skillId)) return fromEvent;
  return [...document.querySelectorAll('.skill-execution-settings')]
    .find(card => card.dataset.skillId === String(skillId)) || null;
}

function _setSkillExecutionStatus(card, state, text) {
  const status = card?.querySelector('.skill-execution-status');
  if (!status) return;
  status.dataset.state = state || '';
  status.textContent = text || '';
}

function _setSkillExecutionDisabled(card, disabled) {
  card?.querySelectorAll('select').forEach(select => { select.disabled = disabled; });
}

function _applySkillExecutionToCard(card, execution) {
  if (!card) return;
  const normalized = _normalizeSkillExecution(execution);
  const modelSelect = card.querySelector('.skill-execution-model');
  const effortSelect = card.querySelector('.skill-execution-effort');
  if (modelSelect) modelSelect.innerHTML = _skillExecutionModelOptionsHtml(normalized);
  if (effortSelect) {
    effortSelect.innerHTML = _skillExecutionEffortOptionsHtml(
      normalized.reasoningEffort,
      card._supportedExecutionEfforts || _SKILL_EXECUTION_EFFORT_OPTIONS,
    );
  }
  let hint = null;
  try { hint = JSON.parse(card.dataset.executionHint || '{}'); } catch { hint = null; }
  if (hint && !hint.tier && !hint.effort) hint = null;
  const summary = card.querySelector('.skill-execution-current');
  if (summary) summary.textContent = _skillExecutionSummary(normalized, hint);
}

function _skillExecutionPayloadFromCard(card) {
  const pair = _parseSkillExecutionModelValue(card?.querySelector('.skill-execution-model')?.value || '');
  const effort = card?.querySelector('.skill-execution-effort')?.value || null;
  return { provider: pair.provider, model: pair.model, reasoningEffort: effort };
}

async function _reloadSkillExecution(skillId) {
  const response = await fetch('/api/roles');
  if (!response.ok) throw new Error('Could not reload execution setting');
  const skills = await response.json();
  const skill = Array.isArray(skills) ? skills.find(item => item.id === skillId) : null;
  if (!skill) throw new Error('Role or skill is no longer available');
  return _normalizeSkillExecution(skill.execution);
}

async function saveSkillExecution(skillId, event) {
  const card = _skillExecutionCard(skillId, event);
  if (!card) return;
  const prior = _skillExecutionSaved.get(skillId) || _normalizeSkillExecution(null);
  const changedModel = event?.target?.classList?.contains('skill-execution-model');
  const payload = _skillExecutionPayloadFromCard(card);
  _setSkillExecutionDisabled(card, true);
  _setSkillExecutionStatus(card, 'saving', 'Saving…');
  try {
    const response = await fetch(`/api/roles/${encodeURIComponent(skillId)}/execution`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(result.error || 'Save failed');
    const saved = _normalizeSkillExecution(result.execution);
    _skillExecutionSaved.set(skillId, saved);
    _applySkillExecutionToCard(card, saved);
    _setSkillExecutionStatus(card, 'saved', 'Saved');
    if (changedModel) refreshSkillExecutionEfforts(skillId, { target: card });
    setTimeout(() => {
      const status = card.querySelector('.skill-execution-status');
      if (status?.dataset.state === 'saved') _setSkillExecutionStatus(card, '', '');
    }, 1800);
  } catch (error) {
    _setSkillExecutionStatus(card, 'saving', 'Save failed — restoring…');
    let restored = prior;
    try { restored = await _reloadSkillExecution(skillId); } catch {}
    _skillExecutionSaved.set(skillId, restored);
    _applySkillExecutionToCard(card, restored);
    _setSkillExecutionStatus(card, 'error', `Failed: ${error.message || 'save failed'}`);
  } finally {
    _setSkillExecutionDisabled(card, false);
  }
}

async function refreshSkillExecutionEfforts(skillId, event) {
  const card = _skillExecutionCard(skillId, event);
  if (!card) return;
  if (event?.type === 'toggle' && !event.target?.open) return;
  const selected = card.querySelector('.skill-execution-model')?.value || card.dataset.inheritedModel || '';
  const { provider, model } = _parseSkillExecutionModelValue(selected);
  if (!provider || !model) return;
  const effortSelect = card.querySelector('.skill-execution-effort');
  const current = effortSelect?.value || null;
  const requestId = (_skillExecutionEffortRequests.get(skillId) || 0) + 1;
  _skillExecutionEffortRequests.set(skillId, requestId);
  effortSelect?.setAttribute('aria-busy', 'true');
  try {
    const params = new URLSearchParams({ provider, model });
    const response = await fetch(`/api/reasoning-efforts?${params}`);
    const result = await response.json().catch(() => ({}));
    if (!response.ok || !Array.isArray(result.options)) return;
    if (_skillExecutionEffortRequests.get(skillId) !== requestId) return;
    card._supportedExecutionEfforts = result.options;
    if (effortSelect) effortSelect.innerHTML = _skillExecutionEffortOptionsHtml(current, result.options);
  } catch {
    // The generic list remains usable if capability discovery is temporarily unavailable.
  } finally {
    if (_skillExecutionEffortRequests.get(skillId) === requestId) effortSelect?.removeAttribute('aria-busy');
  }
}

function refreshSkillExecutionModelSelects() {
  document.querySelectorAll('.skill-execution-settings').forEach(card => {
    const saved = _skillExecutionSaved.get(card.dataset.skillId) || _normalizeSkillExecution(null);
    _applySkillExecutionToCard(card, saved);
  });
}

async function loadSkillsList() {
  const rolesEl = $('rolesList');
  const skillsEl = $('skillsList');
  const customEl = $('customSkillsList');
  if (!rolesEl && !skillsEl && !customEl) return;
  const isPriv = _currentUser?.role === 'owner' || _currentUser?.role === 'admin';
  try {
    const [skills, allAgents, cfg] = await Promise.all([
      fetch('/api/roles').then(r => r.json()),
      fetch('/api/agents').then(r => r.json()),
      fetch('/api/config-public').then(r => r.json()).catch(() => ({})),
    ]);
    const roles = skills.filter(s => s.service);
    // A skill is "custom" iff it was installed under users/<id>/skills/ — the
    // API surfaces that as userScope=<id>. The manifest's `custom` field is
    // unreliable (some built-in role manifests historically set it too), so
    // we trust userScope as the single source of truth. Service roles are
    // always shown in the Roles section, never duplicated under Custom.
    const isCustom = (s) => !!s.userScope && !s.service && s.category !== 'delegate';
    const tools = skills.filter(s => !s.service && s.category !== 'delegate' && !isCustom(s));
    const customSkills = skills.filter(isCustom);
    const assignableAgents = (allAgents ?? []).filter(a => !a.archived);

    function skillActivationControl(s) {
      const privileged = _currentUser?.role === 'owner' || _currentUser?.role === 'admin';
      const managed = _currentUser?.skillsLocked === true && !privileged;
      const toggleArgs = JSON.stringify([s.id, '$checked']).replace(/'/g, "&#39;");
      if (s.always_on) {
        return '<span style="font-size:10px;color:var(--muted);white-space:nowrap">Always on</span>';
      }
      return `<label style="display:flex;align-items:center;gap:6px;font-size:10px;color:var(--muted);cursor:${managed ? 'not-allowed' : 'pointer'};white-space:nowrap">
        <input type="checkbox" ${s.enabled ? 'checked' : ''} ${managed ? 'disabled' : ''}
          data-change-action="toggleSkill" data-change-args='${toggleArgs}'
          aria-label="${s.enabled ? 'Disable' : 'Enable'} ${escHtml(s.name)}"
          style="accent-color:var(--accent);cursor:${managed ? 'not-allowed' : 'pointer'}">
        <span>${managed ? 'Managed' : (s.enabled ? 'Enabled' : 'Disabled')}</span>
      </label>`;
    }

    function roleCard(s) {
      const owner = s.assignment ? (allAgents.find(a => a.id === s.assignment) ?? null) : null;
      const delegationHtml = owner
        ? `<div style="font-size:10px;color:var(--muted);margin-top:3px">${escHtml(owner.emoji ?? '')} ${escHtml(owner.name)}</div>`
        : `<div style="font-size:10px;color:var(--muted);margin-top:3px;font-style:italic">Unassigned</div>`;
      const deleteBtn = isPriv
        ? `<button data-action="deleteRole" data-args='${JSON.stringify([s.id]).replace(/'/g, "&#39;")}' title="Delete"
             class="role-delete-btn"
             style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:14px;padding:4px 2px;flex-shrink:0;line-height:1">✕</button>`
        : '';
      return `<div class="skill-settings-card">
        <div class="skill-settings-card-head">
          <span style="font-size:20px;flex-shrink:0;margin-top:1px">${s.icon ?? '🎯'}</span>
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:600;color:var(--text)">${escHtml(s.name)}</div>
            ${s.description ? `<div style="font-size:11px;color:var(--muted)">${escHtml(s.description)}</div>` : ''}
            ${delegationHtml}
          </div>
          ${skillActivationControl(s)}
          ${deleteBtn}
        </div>
        ${_renderSkillExecutionControls(s, allAgents)}
      </div>`;
    }

    function toolCard(s) {
      return `<div class="skill-settings-card">
        <div class="skill-settings-card-head">
          <span style="font-size:18px;flex-shrink:0">${s.icon ?? '🔧'}</span>
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:600;color:var(--text)">${escHtml(s.name)}</div>
            ${s.description ? `<div style="font-size:11px;color:var(--muted)">${escHtml(s.description)}</div>` : ''}
          </div>
          ${skillActivationControl(s)}
        </div>
        ${_renderSkillExecutionControls(s, allAgents)}
      </div>`;
    }

    function customSkillCard(s) {
      const owner = s.assignment ? assignableAgents.find(a => a.id === s.assignment) : null;
      const ownerLabel = owner
        ? `${escHtml(owner.emoji ?? '')} ${escHtml(owner.name)}`
        : `<span style="color:var(--red)">Unassigned — no agent can use this</span>`;
      const options = ['<option value="">— Unassigned —</option>']
        .concat(assignableAgents.map(a =>
          `<option value="${escHtml(a.id)}"${a.id === s.assignment ? ' selected' : ''}>${escHtml(a.emoji ?? '')} ${escHtml(a.name)}</option>`
        )).join('');
      return `<div class="skill-settings-card">
        <div class="skill-settings-card-head">
          <span style="font-size:18px;flex-shrink:0;margin-top:1px">${s.icon ?? '🧩'}</span>
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:600;color:var(--text)">${escHtml(s.name)}</div>
            ${s.description ? `<div style="font-size:11px;color:var(--muted)">${escHtml(s.description)}</div>` : ''}
            <div style="font-size:10px;color:var(--muted);margin-top:4px">Assigned to: ${ownerLabel}</div>
            <div style="display:flex;gap:6px;align-items:center;margin-top:6px">
              <select data-change-action="assignCustomSkill" data-args='${JSON.stringify([s.id]).replace(/'/g, "&#39;")}'
                style="flex:1;min-width:0;background:var(--bg2);color:var(--text);border:1px solid var(--border);border-radius:6px;padding:5px 7px;font-size:11px">
                ${options}
              </select>
            </div>
          </div>
          ${skillActivationControl(s)}
        </div>
        ${_renderSkillExecutionControls(s, allAgents)}
      </div>`;
    }

    const noAccessMsg = `<div style="color:var(--muted);font-size:12px;font-style:italic">Access is managed by your administrator.</div>`;

    // ── Roles panel ──
    if (rolesEl) {
      if (!isPriv && roles.length === 0) {
        rolesEl.innerHTML = noAccessMsg;
      } else {
        let html = `<div style="display:flex;flex-direction:column;gap:8px">` + roles.map(roleCard).join('') + `</div>`;
        if (isPriv) {
          html += `<button data-action="openNewRoleModal"
            class="new-role-btn"
            style="width:100%;background:var(--bg3);border:1px dashed var(--border);color:var(--muted);border-radius:8px;padding:9px;font-size:12px;cursor:pointer;margin-top:8px;font-weight:500">+ New Role</button>`;
        }
        rolesEl.innerHTML = html;
      }
    }

    // ── Custom skills panel ──
    if (customEl) {
      if (!isPriv && customSkills.length === 0) {
        customEl.innerHTML = `<div style="color:var(--muted);font-size:12px;font-style:italic">No custom skills yet. Ask the coordinator: "create a skill that …" to build one.</div>`;
      } else if (customSkills.length === 0) {
        customEl.innerHTML = `<div style="color:var(--muted);font-size:12px">No custom skills installed. Ask the coordinator to create one, or install one from the community catalog.</div>`;
      } else {
        customEl.innerHTML = `<div style="display:flex;flex-direction:column;gap:8px">` + customSkills.map(customSkillCard).join('') + `</div>`;
      }
    }

    // ── Tools panel — built-in (non-custom) tools only ──
    if (skillsEl) {
      if (!isPriv && tools.length === 0) {
        skillsEl.innerHTML = noAccessMsg;
      } else {
        skillsEl.innerHTML = tools.length
          ? `<div style="display:flex;flex-direction:column;gap:8px">` + tools.map(toolCard).join('') + `</div>`
          : `<div style="color:var(--muted);font-size:12px">No tools available.</div>`;
      }
    }
  } catch (e) {
    const msg = `<div style="color:var(--red);font-size:12px">${escHtml(e.message)}</div>`;
    if (rolesEl) rolesEl.innerHTML = msg;
    if (skillsEl) skillsEl.innerHTML = msg;
  }
}

function _closeNewRoleModal() { $('newRoleModal')?.remove(); }

async function deleteRole(id) {
  if (!confirm('Delete this role? This cannot be undone.')) return;
  try {
    const r = await fetch(`/api/roles/${encodeURIComponent(id)}`, { method: 'DELETE' });
    if (!r.ok) throw new Error((await r.json()).error);
    showToast('Role deleted');
    _skillsCache = null;
    loadSkillsList();
  } catch (e) { showToast(e.message || 'Failed to delete'); }
}

async function assignCustomSkill(skillId, ev) {
  const agentId = ev?.target?.value || null;
  try {
    const r = await fetch('/api/roles/assign', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ skillId, agentId }),
    });
    if (!r.ok) throw new Error((await r.json()).error ?? 'Assignment failed');
    showToast(agentId ? 'Skill assigned' : 'Skill unassigned');
    _skillsCache = null;
    loadSkillsList();
  } catch (e) { showToast(e.message || 'Failed to assign'); loadSkillsList(); }
}

function openNewRoleModal() {
  let modal = $('newRoleModal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'newRoleModal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px';
    modal.innerHTML = `
      <div style="background:var(--bg2);border:1px solid var(--border);border-radius:12px;padding:20px;width:100%;max-width:440px;display:flex;flex-direction:column;gap:12px">
        <div style="font-size:15px;font-weight:700;color:var(--text)">New Role</div>
        <div style="display:flex;gap:8px">
          <input id="newRoleIcon" placeholder="🎯" maxlength="4"
            style="width:52px;text-align:center;font-size:18px;background:var(--bg3);border:1px solid var(--border);color:var(--text);border-radius:8px;padding:8px">
          <input id="newRoleName" placeholder="Role name (e.g. Researcher)"
            style="flex:1;background:var(--bg3);border:1px solid var(--border);color:var(--text);border-radius:8px;padding:8px 10px;font-size:13px">
        </div>
        <input id="newRoleDesc" placeholder="Short description (shown in Tools tab)"
          style="background:var(--bg3);border:1px solid var(--border);color:var(--text);border-radius:8px;padding:8px 10px;font-size:13px">
        <textarea id="newRoleResp" rows="5" placeholder="Responsibilities — injected into the agent's system prompt when this role is active"
          style="background:var(--bg3);border:1px solid var(--border);color:var(--text);border-radius:8px;padding:8px 10px;font-size:12px;resize:vertical;font-family:inherit"></textarea>
        <div id="newRoleError" style="font-size:11px;color:var(--red,#e05c5c);min-height:14px"></div>
        <div style="display:flex;gap:8px;justify-content:flex-end">
          <button data-action="_closeNewRoleModal"
            style="background:none;border:1px solid var(--border);color:var(--muted);border-radius:8px;padding:8px 16px;font-size:12px;cursor:pointer">Cancel</button>
          <button data-action="submitNewRole"
            style="background:var(--accent);border:none;color:#fff;border-radius:8px;padding:8px 16px;font-size:12px;cursor:pointer;font-weight:600">Create Role</button>
        </div>
      </div>`;
    document.body.appendChild(modal);
    modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });
  }
  modal.style.display = 'flex';
  $('newRoleName')?.focus();
}

async function submitNewRole() {
  const name = $('newRoleName')?.value.trim();
  const icon = $('newRoleIcon')?.value.trim();
  const description = $('newRoleDesc')?.value.trim();
  const responsibilities = $('newRoleResp')?.value.trim();
  const errEl = $('newRoleError');
  if (!name) { if (errEl) errEl.textContent = 'Name is required'; return; }
  try {
    const r = await fetch('/api/roles', { method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, icon, description, responsibilities }) });
    const data = await r.json();
    if (!r.ok) { if (errEl) errEl.textContent = data.error; return; }
    $('newRoleModal')?.remove();
    showToast(`Role "${name}" created`);
    _skillsCache = null;
    loadSkillsList();
  } catch { if (errEl) errEl.textContent = 'Failed to create role'; }
}

async function _setSkillEnabled(skillId, enabled) {
  const response = await fetch('/api/roles/toggle', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ skillId, enabled }),
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(result.error || `Could not ${enabled ? 'enable' : 'disable'} this tool`);
  }
  if (typeof result.enabled !== 'boolean' || !Array.isArray(result.skills)) {
    throw new Error('OE returned an invalid tool status');
  }
  return result;
}

async function toggleSkill(skillId, enabled, event) {
  const control = event?.target?.matches?.('input[type="checkbox"]') ? event.target : null;
  if (control) control.disabled = true;
  let result;
  try {
    result = await _setSkillEnabled(skillId, enabled);
  } catch (e) {
    if (control) control.checked = !enabled;
    showToast(e?.message || `Could not ${enabled ? 'enable' : 'disable'} this tool`);
    if (control?.isConnected) control.disabled = false;
    return;
  }

  // The mutation is committed. Keep the authoritative state even when a
  // secondary roster/settings refresh happens to fail.
  if (control) {
    control.checked = result.enabled;
    control.setAttribute?.('aria-label', `${result.enabled ? 'Disable' : 'Enable'} ${skillId === 'browser-ext' ? 'agent browser access' : 'tool'}`);
    if (control.nextElementSibling) {
      control.nextElementSibling.textContent = skillId === 'browser-ext'
        ? (result.enabled ? 'On' : 'Off')
        : (result.enabled ? 'Enabled' : 'Disabled');
    }
  }
  if (_currentUser) _currentUser = { ..._currentUser, skills: result.skills };
  _skillsCache = null;
  showToast(`${result.enabled ? 'Enabled' : 'Disabled'} ${skillId === 'browser-ext' ? 'Browser Extension' : 'tool'}`);

  try {
    const updated = await fetch('/api/agents').then(r => r.json());
    agents = updated;
    buildTabs();
    buildAgentDrawer();
  } catch (e) {
    console.warn('[skills] roster refresh after toggle failed:', e);
  }
  try { await loadSkillsList(); }
  catch (e) { console.warn('[skills] settings refresh after toggle failed:', e); }
  if (skillId === 'browser-ext' && typeof loadBrowserBridge === 'function') {
    try { await loadBrowserBridge(); }
    catch (e) { console.warn('[browser] settings refresh after toggle failed:', e); }
  }
  if (control?.isConnected) control.disabled = false;
}

// Credential prompt bubbles — extracted from chat-render.js.
// Globals intentional.

// ── Credential prompt bubble ─────────────────────────────────────────────────
// A tool (or the oe-admin skill) asked the user for a secret. The value is
// pasted into a password-style input and submitted via a NEW WS frame
// (`submit_credential`), bypassing the normal chat input pipeline so it
// never enters the LLM message history. The bubble morphs into a "Provided"
// indicator on submit — the actual value is never rendered to the DOM.
function appendCredentialPromptBubble(credentialId, label, description, kind) {
  if (!credentialId) return;
  if (document.querySelector(`.msg.credential-prompt[data-credential-id="${CSS.escape(credentialId)}"]`)) return;

  const el = document.createElement('div');
  el.className = 'msg credential-prompt';
  el.dataset.credentialId = credentialId;
  el.dataset.credentialKind = kind || 'api_key';
  el.style.cssText = 'padding:10px 12px;margin:6px 0;font-size:13px;border-left:3px solid #f0b400;background:rgba(240,180,0,0.06);border-radius:4px';

  const header = document.createElement('div');
  header.style.cssText = 'display:flex;gap:8px;align-items:center;margin-bottom:6px';
  const icon = document.createElement('span');
  icon.textContent = kind === 'sudo' ? '🔐' : kind === 'confirm' ? '⚠️' : '🔑';
  header.appendChild(icon);
  const labelEl = document.createElement('span');
  labelEl.style.cssText = 'font-weight:600';
  labelEl.textContent = label || 'Enter credential';
  header.appendChild(labelEl);
  el.appendChild(header);

  if (description) {
    const desc = document.createElement('div');
    desc.style.cssText = 'color:var(--muted);font-size:12px;margin-bottom:8px;white-space:pre-wrap';
    desc.textContent = description;
    el.appendChild(desc);
  }
  if (kind === 'sudo') {
    const note = document.createElement('div');
    note.style.cssText = 'color:var(--muted);font-size:11px;margin-bottom:8px';
    note.textContent = 'Used once for this operation. Not stored.';
    el.appendChild(note);
  } else if (kind === 'confirm') {
    const note = document.createElement('div');
    note.style.cssText = 'color:var(--muted);font-size:11px;margin-bottom:8px';
    note.textContent = 'Type the exact confirmation phrase shown above.';
    el.appendChild(note);
  }

  const form = document.createElement('form');
  form.style.cssText = 'display:flex;gap:6px;align-items:center';

  const input = document.createElement('input');
  input.type = kind === 'confirm' ? 'text' : 'password';
  input.autocomplete = 'off';
  input.spellcheck = false;
  input.style.cssText = 'flex:1;padding:6px 8px;border:1px solid var(--border);background:var(--bg-input, #111);color:var(--fg);border-radius:4px;font-family:inherit;font-size:13px';
  input.placeholder = kind === 'sudo' ? 'sudo password' : kind === 'confirm' ? 'type here…' : 'paste secret here';
  form.appendChild(input);

  const submitBtn = document.createElement('button');
  submitBtn.type = 'submit';
  submitBtn.textContent = 'Submit';
  submitBtn.style.cssText = 'padding:6px 12px;border:1px solid var(--accent, #6c8cff);background:var(--accent, #6c8cff);color:#fff;border-radius:4px;cursor:pointer;font-size:12px';
  form.appendChild(submitBtn);

  const cancelBtn = document.createElement('button');
  cancelBtn.type = 'button';
  cancelBtn.textContent = 'Cancel';
  cancelBtn.style.cssText = 'padding:6px 12px;border:1px solid var(--border);background:transparent;color:var(--muted);border-radius:4px;cursor:pointer;font-size:12px';
  form.appendChild(cancelBtn);

  form.addEventListener('submit', (ev) => {
    ev.preventDefault();
    const value = input.value;
    if (!value) return;
    // Clear input immediately — the value lives only on the wire from here.
    input.value = '';
    submitBtn.disabled = true;
    cancelBtn.disabled = true;
    submitBtn.textContent = 'Submitting…';
    try {
      ws.send(JSON.stringify({ type: 'submit_credential', credentialId, value }));
    } catch (e) {
      markCredentialBubbleError(credentialId, 'send_failed');
    }
  });
  cancelBtn.addEventListener('click', () => {
    submitBtn.disabled = true;
    cancelBtn.disabled = true;
    cancelBtn.textContent = 'Cancelled';
    try { ws.send(JSON.stringify({ type: 'cancel_credential', credentialId })); } catch {}
  });

  el.appendChild(form);
  insertBefore(el);
  scrollToBottom();
}

function resolveCredentialBubble(credentialId, cancelled) {
  const el = document.querySelector(`.msg.credential-prompt[data-credential-id="${CSS.escape(credentialId)}"]`);
  if (!el) return;
  const form = el.querySelector('form');
  if (form) form.remove();
  const status = document.createElement('div');
  status.style.cssText = 'color:var(--muted);font-size:12px';
  status.textContent = cancelled ? 'Cancelled.' : 'Provided.';
  el.appendChild(status);
}

function markCredentialBubbleError(credentialId, error) {
  const el = document.querySelector(`.msg.credential-prompt[data-credential-id="${CSS.escape(credentialId)}"]`);
  if (!el) return;
  const err = document.createElement('div');
  err.style.cssText = 'color:#f55;font-size:12px;margin-top:6px';
  err.textContent = 'Error: ' + (error || 'unknown');
  el.appendChild(err);
}

// Proposals, attachment decisions, approvals, watcher history — extracted from chat-render.js.
// Globals intentional.

function appendProposalBubble(proposal, scroll = true) {
  const id = proposal.proposalId;
  if (!id) return;
  // De-dupe: if a bubble already exists for this proposal id, leave it alone.
  if (document.querySelector(`.msg.proposal[data-proposal-id="${CSS.escape(id)}"]`)) return;

  const el = document.createElement('div');
  el.className = 'msg proposal';
  el.dataset.proposalId = id;
  // Phase-11a: stash the kind so applyProposalOutcome can render a
  // kind-specific "Learned: X" chip distinct from generic accept.
  if (proposal.kind) el.dataset.proposalKind = proposal.kind;
  el.style.cssText = 'padding:10px 12px;margin:6px 0;font-size:13px;border-left:3px solid var(--accent, #6c8cff);background:rgba(108,140,255,0.06);border-radius:4px';

  const header = document.createElement('div');
  header.style.cssText = 'display:flex;gap:8px;align-items:center;margin-bottom:4px';
  const icon = document.createElement('span');
  icon.textContent = '💡';
  header.appendChild(icon);
  const label = document.createElement('span');
  label.style.cssText = 'font-weight:600';
  const HEADER_BY_KIND = {
    watch:              'Set up a monitor?',
    recurring_task:     'Make this a recurring task?',
    rule_promotion:     'Promote this correction to a standing rule?',
    skill_proposal:     'Bundle this workflow into a skill?',
    skill_refine:       'Refine this skill based on your corrections?',
    skill_deprecation:  'This skill keeps getting corrected — delete it?',
    routine_proposal:   'Save this as a voice routine?',
    alias_proposal:     'Remember this phrase shortcut?',
    personalization_offer:    'A suggestion based on what I\'ve noticed',
    personalization_graduate: 'Always do this from now on?',
  };
  label.textContent = HEADER_BY_KIND[proposal.kind] || 'Proposal';
  header.appendChild(label);
  el.appendChild(header);

  const body = document.createElement('div');
  body.style.cssText = 'color:var(--muted);font-size:12px;margin-bottom:8px;white-space:pre-wrap';
  // Friction proposals (watch / recurring_task) are the only kinds whose
  // server-side message text is the bare user phrasing — they need the
  // "You've asked this a few times" preamble for context. All other kinds
  // already build a self-contained body server-side, so render their message
  // verbatim.
  const isFrictionKind = proposal.kind === 'watch' || proposal.kind === 'recurring_task';
  body.textContent = isFrictionKind
    ? `You've asked this a few times: "${proposal.message}"`
    : (proposal.message || '');
  el.appendChild(body);

  const actions = document.createElement('div');
  actions.style.cssText = 'display:flex;gap:8px';

  const acceptBtn = document.createElement('button');
  acceptBtn.textContent = proposal.accept_label || 'Set it up';
  acceptBtn.style.cssText = 'padding:6px 12px;border:1px solid var(--accent, #6c8cff);background:var(--accent, #6c8cff);color:#fff;border-radius:4px;cursor:pointer;font-size:12px';
  acceptBtn.addEventListener('click', () => respondToProposal(el, id, 'accept', acceptBtn, dismissBtn));
  actions.appendChild(acceptBtn);

  const dismissBtn = document.createElement('button');
  dismissBtn.textContent = proposal.dismiss_label || 'No thanks';
  dismissBtn.style.cssText = 'padding:6px 12px;border:1px solid var(--border);background:transparent;color:var(--muted);border-radius:4px;cursor:pointer;font-size:12px';
  dismissBtn.addEventListener('click', () => respondToProposal(el, id, 'dismiss', acceptBtn, dismissBtn));
  actions.appendChild(dismissBtn);

  // Permanent opt-out — dismiss only snoozes this pattern for 24h; this one
  // records it so it's never proposed again.
  const neverBtn = document.createElement('button');
  neverBtn.textContent = "Don't propose again";
  neverBtn.title = 'Never suggest this again (a normal dismiss only hides it for 24h)';
  neverBtn.style.cssText = 'padding:6px 12px;border:none;background:transparent;color:var(--muted);border-radius:4px;cursor:pointer;font-size:12px;text-decoration:underline;opacity:0.75';
  neverBtn.addEventListener('click', () => respondToProposal(el, id, 'never', acceptBtn, dismissBtn));
  actions.appendChild(neverBtn);

  el.appendChild(actions);
  insertBefore(el);
  if (scroll) scrollToBottom();
}

// Apply a proposal_outcome event against an already-rendered proposal
// bubble — mutates the bubble in place. Three sources call this:
//   1. session-load render pass (replay of persisted proposal_outcome entries)
//   2. WS push of type 'proposal_outcome' (live update from server)
//   3. respondToProposal local optimism on click (best-effort — the WS push
//      will overwrite with the authoritative server state)
//
// Status progression: pending → running → (accepted | dismissed | failed).
// Idempotent within a status: re-applying the same status leaves the bubble
// unchanged. Earlier statuses are also safe to apply but get overwritten on
// the next call. Buttons are removed once the bubble leaves the pending
// state — re-clicking would call /accept on a non-pending proposal.
function applyProposalOutcome(proposalId, status, outcome) {
  const el = document.querySelector(`.msg.proposal[data-proposal-id="${CSS.escape(proposalId)}"]`);
  if (!el) return;
  if (el.dataset.appliedStatus === status) return;
  el.dataset.appliedStatus = status;

  // Strip any previous footer (buttons or outcome line) and rebuild.
  const footer = el.querySelector('.proposal-footer');
  if (footer) footer.remove();
  const buttonRow = [...el.children].find(c => c.querySelector?.('button'));
  if (buttonRow && status !== 'pending') buttonRow.remove();

  const outcomeEl = document.createElement('div');
  outcomeEl.className = 'proposal-footer';
  outcomeEl.style.cssText = 'font-size:12px;color:var(--muted);font-style:italic;margin-top:6px';

  if (status === 'running') {
    // Don't overwrite color — keep it the original accent so it reads as
    // "in flight" rather than completed.
    outcomeEl.textContent = `… ${outcome || 'Setting it up…'}`;
  } else if (status === 'accepted') {
    el.style.borderLeftColor = 'var(--green, #4caf50)';
    el.style.background = 'rgba(76,175,80,0.06)';
    outcomeEl.textContent = `✓ Accepted${outcome ? ` — ${outcome}` : ''}`;
    // Phase-13: inline undo button for kinds we can revoke. Visible for 24h
    // after acceptance; after that the user uses the Learn drawer's revoke.
    const UNDOABLE_KINDS = new Set(['rule_promotion', 'alias_proposal', 'routine_proposal', 'default_arg', 'routing_override']);
    if (UNDOABLE_KINDS.has(el.dataset.proposalKind)) {
      const undoBtn = document.createElement('button');
      undoBtn.textContent = 'Undo';
      undoBtn.style.cssText = 'margin-left:8px;background:transparent;border:1px solid var(--border);border-radius:3px;padding:1px 8px;font-size:11px;color:var(--muted);cursor:pointer;vertical-align:middle';
      undoBtn.title = 'Revert within 24h';
      undoBtn.onclick = async () => {
        undoBtn.disabled = true; undoBtn.textContent = '…';
        try {
          const r = await fetch(`/api/proposals/${encodeURIComponent(el.dataset.proposalId)}/undo`, { method: 'POST' });
          if (!r.ok) {
            const e = await r.json().catch(() => ({}));
            alert(`Undo failed: ${e.error || r.statusText}`);
            undoBtn.disabled = false; undoBtn.textContent = 'Undo';
          }
        } catch (e) { alert(`Undo failed: ${e.message}`); undoBtn.disabled = false; undoBtn.textContent = 'Undo'; }
      };
      outcomeEl.appendChild(undoBtn);
    }
    // Phase-11a: NL chip — kind-specific badge for accepted learnings. Tells
    // the user at a glance what category of customization just stuck.
    const LEARNING_KIND_LABELS = {
      rule_promotion:   'Rule learned',
      alias_proposal:   'Alias learned',
      routine_proposal: 'Routine learned',
      default_arg:      'Default pinned',
      routing_override: 'Routing learned',
      location_fact:    'Location learned',
      skill_proposal:   'Skill built',
    };
    const kind = el.dataset.proposalKind;
    const label = LEARNING_KIND_LABELS[kind];
    if (label && !el.querySelector('.learning-chip')) {
      const chip = document.createElement('span');
      chip.className = 'learning-chip';
      chip.textContent = label;
      chip.style.cssText = 'display:inline-block;font-size:10px;text-transform:uppercase;letter-spacing:0.05em;background:var(--green,#4caf50);color:#fff;padding:1px 6px;border-radius:3px;margin-left:8px;vertical-align:middle';
      const header = el.querySelector('div');   // first <div> = bubble header row
      if (header) header.appendChild(chip);
    }
  } else if (status === 'done') {
    // Terminal status used by the personalization kinds (offer/graduate) —
    // render like 'accepted' and keep the receipt text ('Done — Reminder ...').
    el.style.borderLeftColor = 'var(--green, #4caf50)';
    el.style.background = 'rgba(76,175,80,0.06)';
    outcomeEl.textContent = outcome ? `✓ ${outcome}` : '✓ Done';
  } else if (status === 'dismissed') {
    el.style.opacity = '0.6';
    outcomeEl.textContent = '✕ Dismissed';
  } else if (status === 'failed') {
    el.style.borderLeftColor = 'var(--red, #f44336)';
    el.style.background = 'rgba(244,67,54,0.06)';
    outcomeEl.textContent = `⚠ ${outcome || 'Failed'}`;
  } else if (status === 'undone') {
    el.style.borderLeftColor = 'var(--border)';
    el.style.background = 'transparent';
    el.style.opacity = '0.55';
    // Remove any prior learning-chip badge — the learning has been reverted
    const chip = el.querySelector('.learning-chip');
    if (chip) chip.remove();
    outcomeEl.textContent = `↩ ${outcome || 'Reverted'}`;
  } else {
    outcomeEl.textContent = `· ${status}`;
  }
  el.appendChild(outcomeEl);
}

async function respondToProposal(el, id, action, acceptBtn, dismissBtn) {
  acceptBtn.disabled = true; dismissBtn.disabled = true;
  acceptBtn.style.opacity = '0.5'; dismissBtn.style.opacity = '0.5';
  try {
    const r = await fetch(`/api/proposals/${encodeURIComponent(id)}/${action}`, { method: 'POST' });
    const data = await r.json().catch(() => ({}));
    if (action === 'accept') {
      // Server accepted asynchronously — render the in-flight state. The
      // authoritative final outcome arrives via WS 'proposal_outcome' push
      // when the agent run completes (success or retry-exhausted failure).
      applyProposalOutcome(id, data.ok ? 'running' : 'failed', data.ok ? 'Setting it up…' : `Couldn’t set it up: ${data.error || 'unknown'}`);
    } else {
      // Dismiss is fast (no agent run) — apply final state immediately.
      applyProposalOutcome(id, 'dismissed', null);
    }
  } catch (e) {
    acceptBtn.disabled = false; dismissBtn.disabled = false;
    acceptBtn.style.opacity = '1'; dismissBtn.style.opacity = '1';
    alert('Proposal action failed: ' + e.message);
  }
}

// Attachment save/discard prompt. Emitted by chat-dispatch at the end of any
// turn that had a file attachment (drag-drop, paste, or attach button). The
// upload always lands in users/<id>/profile-files/{kind}/ — this bubble is
// the only "did you mean to keep that?" gate so casual one-shot uploads don't
// silently pile up in Docs. Persisted as role:'attachment_decision' so a
// reload still shows the choice; outcome arrives as role:'attachment_decision_outcome'.
function appendAttachmentDecisionBubble(decision, scroll = true) {
  const id = decision.decisionId;
  if (!id) return;
  if (document.querySelector(`.msg.attachment-decision[data-decision-id="${CSS.escape(id)}"]`)) return;

  const el = document.createElement('div');
  el.className = 'msg attachment-decision';
  el.dataset.decisionId = id;
  el.dataset.fileId = decision.file_id || '';
  el.style.cssText = 'padding:8px 12px;margin:6px 0;font-size:13px;border-left:3px solid var(--muted, #888);background:rgba(128,128,128,0.06);border-radius:4px;display:flex;align-items:center;gap:10px;flex-wrap:wrap';

  const label = document.createElement('span');
  label.style.cssText = 'flex:1;min-width:0;color:var(--muted);font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
  const safeName = escHtml(decision.name || 'attachment');
  label.innerHTML = `Keep <strong style="color:var(--text)">${safeName}</strong> in your files?`;
  el.appendChild(label);

  const keepBtn = document.createElement('button');
  keepBtn.textContent = 'Keep';
  keepBtn.style.cssText = 'padding:4px 12px;border:1px solid var(--accent, #6c8cff);background:var(--accent, #6c8cff);color:#fff;border-radius:4px;cursor:pointer;font-size:12px';
  keepBtn.addEventListener('click', () => respondToAttachmentDecision(el, id, decision.file_id, 'keep', keepBtn, discardBtn));
  el.appendChild(keepBtn);

  const discardBtn = document.createElement('button');
  discardBtn.textContent = 'Discard';
  discardBtn.style.cssText = 'padding:4px 12px;border:1px solid var(--border);background:transparent;color:var(--muted);border-radius:4px;cursor:pointer;font-size:12px';
  discardBtn.addEventListener('click', () => respondToAttachmentDecision(el, id, decision.file_id, 'discard', keepBtn, discardBtn));
  el.appendChild(discardBtn);

  insertBefore(el);
  if (scroll) scrollToBottom();
}

function applyAttachmentDecisionOutcome(decisionId, decision) {
  const el = document.querySelector(`.msg.attachment-decision[data-decision-id="${CSS.escape(decisionId)}"]`);
  if (!el) return;
  if (el.dataset.appliedOutcome === decision) return;
  el.dataset.appliedOutcome = decision;
  // Strip the buttons, leave a one-line resolved note.
  [...el.querySelectorAll('button')].forEach(b => b.remove());
  const label = el.querySelector('span');
  if (label) {
    const name = label.querySelector('strong')?.textContent || 'attachment';
    label.innerHTML = decision === 'keep'
      ? `✓ Kept <strong style="color:var(--text)">${escHtml(name)}</strong> in your files.`
      : `✕ Discarded <strong style="color:var(--text)">${escHtml(name)}</strong>.`;
  }
  el.style.borderLeftColor = decision === 'keep' ? 'var(--green, #4caf50)' : 'var(--border)';
}

async function respondToAttachmentDecision(el, decisionId, fileId, decision, keepBtn, discardBtn) {
  keepBtn.disabled = true; discardBtn.disabled = true;
  keepBtn.style.opacity = '0.5'; discardBtn.style.opacity = '0.5';
  try {
    const r = await fetch('/api/chat-attachment-decision', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ decisionId, file_id: fileId, decision, agent: activeAgent,
        projectId: typeof activeProjectSpaceId === 'string' ? activeProjectSpaceId : null,
        chatId: typeof activeSavedChatId === 'string' ? activeSavedChatId : null }),
    });
    if (!r.ok) throw new Error(await r.text());
    applyAttachmentDecisionOutcome(decisionId, decision);
  } catch (e) {
    keepBtn.disabled = false; discardBtn.disabled = false;
    keepBtn.style.opacity = '1'; discardBtn.style.opacity = '1';
    alert('Couldn’t save your choice: ' + e.message);
  }
}

// Pending-approval pill. Emitted by chat-dispatch's post-turn diff (see
// snapshotPendingApprovals in chat-dispatch.mjs) whenever one of the four
// staged destructive-op families — email purge/batch-trash, expense delete,
// profile trust-state promotion, cross-agent watcher op — is pending after a
// turn. Approve sends the exact confirmation phrase as a normal chat message
// (the server's existing tryApprovalIntercept text match executes it
// unchanged, so the keyboard path keeps working too); modern Cancel buttons
// send a targeted CANCEL APPROVAL #opId phrase so a stale card cannot clear a
// newer operation (legacy cards without an id retain the old fallback).
// Persisted as role:'approval_pending' so a reload still shows it; the
// resolution arrives as role:'approval_resolved' (applyApprovalResolved).
function appendApprovalPendingBubble(pending, scroll = true) {
  const kind = pending.kind;
  if (!kind) return;
  const skillActivation = kind === 'skill_activation';
  // Reuse one card per family. A new operation belongs beside its current
  // request; duplicate events for the same operation stay in place.
  const existing = document.querySelector(`.msg.approval-pending[data-approval-kind="${CSS.escape(kind)}"]`);
  const newOperation = existing && pending.opId && existing.dataset.opId !== pending.opId;
  const el = existing || document.createElement('div');
  if (el._approvalExpiryTimer) {
    clearTimeout(el._approvalExpiryTimer);
    el._approvalExpiryTimer = null;
  }
  if (!existing) {
    el.className = 'msg approval-pending';
    el.dataset.approvalKind = kind;
  }
  // Operation id minted at stage time (lib/pending-approvals.mjs). Sent as a
  // "#<opId>" suffix on Approve so the server can refuse a stale card — one
  // describing an op that was since replaced by a newer staging of the same
  // kind. Absent on legacy rows; those fall back to the bare phrase.
  if (pending.opId) el.dataset.opId = pending.opId;
  else delete el.dataset.opId;
  if (pending.ts != null && Number.isFinite(Number(pending.ts))) el.dataset.approvalTs = String(Number(pending.ts));
  else delete el.dataset.approvalTs;
  delete el.dataset.appliedStatus; // re-pending clears any prior resolved marker
  el.style.cssText = 'padding:10px 12px;margin:6px 0;font-size:13px;border-left:3px solid var(--red, #f44336);background:rgba(244,67,54,0.06);border-radius:4px';
  el.innerHTML = '';

  const label = document.createElement('div');
  label.style.cssText = 'margin-bottom:8px';
  label.innerHTML = `${skillActivation ? '🔌 <strong>Skill not enabled:</strong>' : '⚠️ <strong>Waiting for approval:</strong>'} ${escHtml(pending.description || 'a staged action needs your confirmation')}`;
  el.appendChild(label);

  const actions = document.createElement('div');
  actions.style.cssText = 'display:flex;gap:8px';

  const phrase = pending.phrase || 'APPROVE';
  const approveBtn = document.createElement('button');
  approveBtn.textContent = skillActivation ? 'Enable and continue' : `Approve (${phrase})`;
  approveBtn.style.cssText = 'padding:6px 12px;border:1px solid var(--red, #f44336);background:var(--red, #f44336);color:#fff;border-radius:4px;cursor:pointer;font-size:12px';
  // Read the opId off the element at click time (not capture time) so a
  // re-staged pill that refreshed this bubble in place sends the CURRENT id.
  approveBtn.addEventListener('click', () => respondToApproval(el.dataset.opId ? `${phrase} #${el.dataset.opId}` : phrase, approveBtn, cancelBtn));
  actions.appendChild(approveBtn);

  const cancelBtn = document.createElement('button');
  cancelBtn.textContent = 'Cancel';
  cancelBtn.style.cssText = 'padding:6px 12px;border:1px solid var(--border);background:transparent;color:var(--muted);border-radius:4px;cursor:pointer;font-size:12px';
  cancelBtn.addEventListener('click', () => {
    const currentOpId = el.dataset.opId;
    respondToApproval(currentOpId ? `CANCEL APPROVAL #${currentOpId}` : 'cancel', approveBtn, cancelBtn);
  });
  actions.appendChild(cancelBtn);

  el.appendChild(actions);
  if (!existing || newOperation) insertBefore(el);

  // Watcher approvals currently carry a five-minute expiry. Disable the card
  // at that deadline (including immediately on replay of an already-expired
  // persisted row) so it cannot look actionable after the server has dropped
  // the staged operation. The expected id guard prevents an old timer from
  // disabling a refreshed card for a newer staging of the same kind.
  const expiresAt = typeof pending.expiresAt === 'number'
    ? pending.expiresAt
    : Date.parse(pending.expiresAt || '');
  if (Number.isFinite(expiresAt)) {
    el.dataset.expiresAt = String(expiresAt);
    const expectedOpId = el.dataset.opId || '';
    const expire = () => {
      if ((el.dataset.opId || '') !== expectedOpId) return;
      if (el.dataset.appliedStatus === 'resolved') return;
      const remaining = expiresAt - Date.now();
      if (remaining > 0) {
        el._approvalExpiryTimer = setTimeout(expire, Math.min(remaining, 2_147_483_647));
        return;
      }
      el._approvalExpiryTimer = null;
      el.dataset.appliedStatus = 'expired';
      [...el.querySelectorAll('button')].forEach(b => {
        b.disabled = true;
        b.style.opacity = '0.5';
        b.style.cursor = 'default';
      });
      el.style.borderLeftColor = 'var(--border)';
      el.style.opacity = '0.6';
      const footer = document.createElement('div');
      footer.className = 'approval-status';
      footer.style.cssText = 'font-size:12px;color:var(--muted);font-style:italic;margin-top:6px';
      footer.textContent = '· Expired';
      el.appendChild(footer);
    };
    expire();
  } else {
    delete el.dataset.expiresAt;
  }
  if (scroll) scrollToBottom();
}

// Apply an approval_resolved push (or persisted-session replay of one)
// against an already-rendered pill — mutates in place, mirroring
// applyProposalOutcome / applyAttachmentDecisionOutcome. Fires once the
// staged op is gone: approved-and-executed, or cleared by the "say anything
// else to cancel" rule (any non-matching message clears it server-side).
function applyApprovalResolved(kind, opId = null, resolvedTs = null) {
  if (!kind) return;
  const el = document.querySelector(`.msg.approval-pending[data-approval-kind="${CSS.escape(kind)}"]`);
  if (!el) return;
  const renderedOpId = el.dataset.opId || null;
  // New resolution events must match exactly. For pre-upgrade resolution rows
  // that lack an id, timestamps are the safe migration fallback: only a row at
  // or after this card's staging may resolve it. An older delayed row cannot
  // collapse a newer operation, and rows with no usable correlation stay put.
  if (opId) {
    if (renderedOpId !== opId) return;
  } else if (renderedOpId !== null) {
    const pendingTs = Number(el.dataset.approvalTs);
    const eventTs = resolvedTs == null ? NaN : Number(resolvedTs);
    if (!Number.isFinite(pendingTs) || !Number.isFinite(eventTs) || eventTs < pendingTs) return;
  }
  if (el.dataset.appliedStatus === 'resolved') return;
  if (el._approvalExpiryTimer) {
    clearTimeout(el._approvalExpiryTimer);
    el._approvalExpiryTimer = null;
  }
  el.dataset.appliedStatus = 'resolved';
  [...el.querySelectorAll('button')].forEach(b => b.remove());
  el.querySelector('.approval-status')?.remove();
  el.style.borderLeftColor = 'var(--border)';
  el.style.opacity = '0.6';
  const footer = document.createElement('div');
  footer.className = 'approval-status';
  footer.style.cssText = 'font-size:12px;color:var(--muted);font-style:italic;margin-top:6px';
  footer.textContent = '· Resolved';
  el.appendChild(footer);
}

// Approve/Cancel click handler: sends the given text through the existing
// send() pipeline — the same code path as if the user had typed the phrase
// themselves — so the server's text-match intercept handles it. Mirrors
// send()'s guards and restores a half-written composer draft after the action.
function respondToApproval(text, approveBtn, cancelBtn) {
  if (streaming && !awaitingPermission) return;
  if (!ws || ws.readyState !== WebSocket.OPEN) { showToast('Not connected — try again in a moment'); return; }
  if (pendingAttachments.length) { showToast('Send or remove attachments before responding to an approval'); return; }
  approveBtn.disabled = true; cancelBtn.disabled = true;
  approveBtn.style.opacity = '0.5'; cancelBtn.style.opacity = '0.5';
  const input = $('input');
  const prevValue = input.value;
  input.value = text;
  send();
  // send() clears input.value on success. Either way, put back the user's
  // draft; approval buttons should not silently destroy unrelated typing.
  const sent = input.value !== text;
  input.value = prevValue;
  resizeTextarea();
  saveDraftForAgent(activeAgent);
  if (!sent) {
    approveBtn.disabled = false; cancelBtn.disabled = false;
    approveBtn.style.opacity = '1'; cancelBtn.style.opacity = '1';
  }
}

async function toggleWatcherHistory(el, watcherId) {
  let panel = el.querySelector('.watcher-history');
  if (panel && el.dataset.historyOpen === '1') {
    panel.style.display = 'none';
    el.dataset.historyOpen = '0';
    const caret = el.querySelector('.watcher-caret'); if (caret) caret.textContent = '▸';
    return;
  }
  if (!panel) {
    panel = document.createElement('div');
    panel.className = 'watcher-history';
    panel.style.cssText = 'margin-top:6px;padding:6px 8px 4px 26px;border-top:1px dashed var(--border);font-size:11px;font-style:normal;max-height:240px;overflow-y:auto';
    panel.textContent = 'Loading…';
    el.appendChild(panel);
  }
  panel.style.display = 'block';
  el.dataset.historyOpen = '1';
  const caret = el.querySelector('.watcher-caret'); if (caret) caret.textContent = '▾';
  await refreshWatcherHistory(el, watcherId);
}

async function refreshWatcherHistory(el, watcherId) {
  const panel = el.querySelector('.watcher-history');
  if (!panel) return;
  try {
    const r = await fetch(`/api/watchers/${encodeURIComponent(watcherId)}`, { credentials: 'same-origin' });
    if (!r.ok) {
      panel.textContent = r.status === 404 ? 'No history available (watcher reaped).' : `Failed to load history (${r.status}).`;
      return;
    }
    const w = await r.json();
    const entries = Array.isArray(w.history) ? w.history : [];
    if (!entries.length) {
      panel.textContent = 'No progress entries yet.';
      return;
    }
    panel.innerHTML = '';
    for (const entry of entries) {
      const row = document.createElement('div');
      row.style.cssText = 'display:flex;gap:8px;padding:2px 0;line-height:1.4';
      const t = new Date(entry.ts || 0);
      const hh = String(t.getHours()).padStart(2,'0');
      const mm = String(t.getMinutes()).padStart(2,'0');
      const ss = String(t.getSeconds()).padStart(2,'0');
      const time = document.createElement('span');
      time.textContent = `${hh}:${mm}:${ss}`;
      time.style.cssText = 'flex-shrink:0;opacity:0.55;font-variant-numeric:tabular-nums';
      const txt = document.createElement('span');
      txt.textContent = entry.text || '';
      txt.style.cssText = 'flex:1;min-width:0;white-space:pre-wrap;word-break:break-word';
      if (entry.final) {
        if (entry.finalStatus === 'done') txt.style.color = 'var(--green, #4caf50)';
        else if (entry.finalStatus === 'error') txt.style.color = 'var(--red, #f44336)';
      }
      row.appendChild(time); row.appendChild(txt);
      panel.appendChild(row);
    }
  } catch (e) {
    panel.textContent = `Failed to load history: ${e.message}`;
  }
}

let _runInspectorTraces = [];
let _runInspectorSelected = null;
let _runInspectorTarget = 'runInspectorBody';

function fmtRunTime(ts) {
  if (!ts) return 'unknown';
  return new Date(ts).toLocaleString([], {
    month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', second: '2-digit',
  });
}

function fmtDuration(ms) {
  if (!Number.isFinite(ms)) return '—';
  if (ms < 1000) return `${ms} ms`;
  return `${(ms / 1000).toFixed(ms < 10000 ? 1 : 0)} s`;
}

async function loadRunInspector(selectId = null, targetId = 'runInspectorBody') {
  _runInspectorTarget = targetId;
  const body = $(_runInspectorTarget);
  if (!body) return;
  body.innerHTML = '<div class="cdraw-empty">Loading runs…</div>';
  try {
    const data = await fetch('/api/run-inspector?limit=80').then(r => {
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return r.json();
    });
    _runInspectorTraces = data.traces || [];
    _runInspectorSelected = selectId || _runInspectorSelected || _runInspectorTraces[0]?.id || null;
    renderRunInspector();
  } catch (e) {
    body.innerHTML = `<div class="cdraw-empty" style="color:var(--red)">Failed to load runs: ${escHtml(e.message)}</div>`;
  }
}

function renderRunInspector() {
  const body = $(_runInspectorTarget);
  if (!body) return;
  if (!_runInspectorTraces.length) {
    body.innerHTML = '<div class="cdraw-empty">No runs recorded yet.</div>';
    return;
  }
  const selected = _runInspectorTraces.find(t => t.id === _runInspectorSelected) || _runInspectorTraces[0];
  _runInspectorSelected = selected.id;
  body.innerHTML = `
    <div class="run-inspector-list">
      ${_runInspectorTraces.map(t => renderRunInspectorRow(t, t.id === selected.id)).join('')}
    </div>
    <div class="run-inspector-detail" id="${escHtml(_runInspectorTarget)}Detail">
