async function loadRunInspectorDetail(id) {
  const detail = $(`${_runInspectorTarget}Detail`);
  if (!detail) return;
  try {
    const t = await fetch(`/api/run-inspector/${encodeURIComponent(id)}`).then(r => {
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return r.json();
