import { setTimeout as delay } from 'node:timers/promises';
import { consumeProvider, mergeProviderUsage } from './provider-consumer.mjs';
import { isRetrySafeControlTool } from './recovery.mjs';
import { isTransientProviderError } from '../lib/provider-recovery.mjs';

const RETRY_DELAYS = [5_000, 15_000, 30_000];

// Keep retries inside the same turn and cancellation signal. Only restart a
// provider before it has invoked an action; never replay a completed tool.
export async function* consumeProviderWithRetry(providerFactory, { retry = false, signal, ...options } = {}) {
  let prior = null;
  for (let attempt = 0; ; attempt++) {
    let failure = null;
    let effectSeen = false;
    const consumer = consumeProvider(providerFactory(), {
      ...options,
      providerCallOrdinalOffset: (options.providerCallOrdinalOffset || 0) + (prior?.modelCalls.length || 0),
    });
    let result;
    try {
      while (true) {
        const step = await consumer.next();
        if (step.done) { result = step.value; break; }
        const event = step.value;
        if (event.type === 'error') { failure = event; continue; }
        if (['tool_call', 'tool_progress', 'tool_result'].includes(event.type) && !isRetrySafeControlTool(event.name)) effectSeen = true;
        if (['permission_request', 'approval_pending', 'credential_prompt', 'image', 'video', 'hide_turn', '__notify'].includes(event.type)) effectSeen = true;
        yield event;
      }
    } finally { await consumer.return(); }
    if (prior) {
      result.usage = mergeProviderUsage(prior.usage, result.usage);
      for (const field of ['modelCalls', 'toolsUsed', 'toolEvents', 'toolIdentityAnomalies', 'turnImages']) result[field] = [...prior[field], ...result[field]];
    }
    // A paid hosted image request can be accepted before the socket fails.
    // Its provider adapter intentionally forbids replay even without a receipt.
    const paidImageOffered = result.modelCalls.some(call => call.toolNames?.includes('image_generation'));
    const safe = !effectSeen && !paidImageOffered && !result.turnImages.length && !result.toolIdentityAnomalies.length
      && result.toolEvents.every(event => isRetrySafeControlTool(event.name));
    if (!retry || !result.errored || !safe || signal?.aborted
        || attempt >= RETRY_DELAYS.length || !isTransientProviderError(failure)) {
      if (failure) yield failure;
      return result;
    }
    const delayMs = RETRY_DELAYS[attempt];
    yield { type: 'provider_retry', attempt: attempt + 2, maxAttempts: RETRY_DELAYS.length + 1,
      retryAt: Date.now() + delayMs, message: 'The AI connection was interrupted. Retrying automatically…' };
    try { await delay(delayMs, undefined, { signal }); }
    catch (error) { if (signal?.aborted) return result; throw error; }
    if (signal?.aborted) return result;
    // A partial draft is replaced, not concatenated with a second answer.
    yield { type: 'replace', text: '' };
    yield { type: 'provider_retry', attempt: attempt + 2, maxAttempts: RETRY_DELAYS.length + 1, retryAt: null };
    prior = result;
  }
}

// @ts-check
/**
 * Shared autonomy policy helpers.
 *
 * This is intentionally small and deterministic. It centralizes the safety
 * decisions that were previously scattered across watcher/task/proposal code:
 * how automation risk is classified, and how to summarize autonomy
 * state for review surfaces.
 */

const DESTRUCTIVE_RE = /\b(delete|remove|purge|erase|destroy|terminate|shutdown|shut down|kill|drop|truncate|wipe|reset|rollback)\b/i;
const EXTERNAL_SIDE_EFFECT_RE = /\b(send|email|message|post|publish|buy|purchase|order|pay|charge|transfer|deploy|merge|commit|push)\b/i;

export const AUTONOMY_RISK = Object.freeze({
  LOW: 'low',
  SIDE_EFFECT: 'side_effect',
  DESTRUCTIVE: 'destructive',
});

export function classifyAutomationText(text) {
  const s = String(text || '');
  if (DESTRUCTIVE_RE.test(s)) return AUTONOMY_RISK.DESTRUCTIVE;
  if (EXTERNAL_SIDE_EFFECT_RE.test(s)) return AUTONOMY_RISK.SIDE_EFFECT;
  return AUTONOMY_RISK.LOW;
}

export function summarizeAutonomyPolicy() {
  return {
    scheduledTasks: 'runs and results are recorded in Tasks → Ledger, separate from chat; tool authorization still applies',
    execWatchers: 'blocked from agent-created watches unless registered through a human-confirmed route',
    monitorOffers: 'cool down per topic and escalate repeated monitorable questions into review proposals',
    watcherRecovery: 'stuck polling watchers back off cadence and surface status instead of spinning silently',
  };
}

import { loadOwnedInputImage } from '../skills/image_generator/execute.mjs';

export function isImageEditRequest(text) {
  return /\b(?:edit|modify|change|expand|extend|outpaint|recolor|retouch|resize|make|turn)\b/i.test(text)
    && /\b(?:images?|pictures?|photos?|portrait|illustration|full.body|head.to.toe|background|foreground|outfit|hair|lighting|colors?|blue|red|green|black|white)\b/i.test(text);
}

/** Restore one exact source image only for an authorized edit continuation. */
export function imageEditContext(userId, userText, rows) {
  if (!isImageEditRequest(userText)) return null;
  const explicit = userText.match(/\bimages:([^\s/\\<>"'`]+\.(?:png|jpe?g|webp|gif))\b/i)?.[0];
  let id = explicit;
  if (!id) {
    for (const row of [...rows].reverse()) {
      const images = [row?.image, ...(Array.isArray(row?.images) ? row.images : []),
        ...(Array.isArray(row?.attachments) ? row.attachments : [])].filter(Boolean);
      for (const image of [...images].reverse()) {
        const saved = image.savedPath ?? image.file_id;
        if (typeof saved === 'string' && saved.startsWith('images:')) id = saved;
        else if (typeof image.filename === 'string') id = `images:${image.filename}`;
        if (id) break;
      }
      if (id) break;
    }
  }
  if (!id) return null;
  try {
    const dataUrl = loadOwnedInputImage(userId, id);
    const comma = dataUrl.indexOf(',');
    return {
      attachment: { file_id: id, name: id, mimeType: dataUrl.slice(5, dataUrl.indexOf(';')),
        base64: dataUrl.slice(comma + 1) },
      note: `Source image for this edit: ${id}. Edit the attached original and preserve its identity.`,
    };
  } catch {
    return { attachment: null, note: `The source image ${id} could not be loaded for this edit. Ask the user to attach it again; do not claim a new image is an edit of that original.` };
  }
}

/**
 * Resolve a profile's token_storage reference to the actual token value.
 *
 * Supported reference forms (matches what profiles declare):
 *   'config_field:<key>'  → users/<uid>/profile.json[<key>], else config.json[<key>]
 *   'env:<NAME>'          → process.env[NAME]
 *
 * Returns null when not found. Used by the profiles skill, the health-monitor
 * ctxResolver, and anywhere else profile-driven HTTP calls need auth.
 */

import fs from 'fs';
import path from 'path';
import { readConfig, USERS_DIR } from './paths.mjs';

export function resolveTokenStorage(userId, storageRef) {
  if (!storageRef) return null;
  const colon = String(storageRef).indexOf(':');
  if (colon < 0) return null;
  const scheme = storageRef.slice(0, colon);
  const rest = storageRef.slice(colon + 1);

  if (scheme === 'env') {
    return process.env[rest] || null;
  }
  if (scheme === 'config_field') {
    const userProfile = path.join(USERS_DIR, userId, 'profile.json');
    try {
      if (fs.existsSync(userProfile)) {
        const obj = JSON.parse(fs.readFileSync(userProfile, 'utf8'));
        if (obj && obj[rest] !== undefined) return obj[rest];
      }
    } catch {}
    const cfg = readConfig();
    return cfg[rest] ?? null;
  }
  return null;
}

/**
 * Build a (storageRef) → string resolver bound to a userId.
 * Useful as the `resolveAuth` callback in capability-dispatcher's ctx.
 */
export function makeAuthResolver(userId) {
  return (storageRef) => resolveTokenStorage(userId, storageRef);
}

/**
 * Cortex embeddings + salience scoring + contradiction detection.
 */

import { createHash } from 'crypto';
import {
  VECTOR_DIM, getCortexConfig, getProviderSpec, generateCombined, safeParseJSON,
} from './shared.mjs';
import { builtinEmbed } from './builtin-embed.mjs';

// ── Embedding LRU cache ──────────────────────────────────────────────────────
// Recall, forget, and session-buffer code paths can all embed the same query
// text within one request (e.g. recall → forgetByText → contradiction check).
// A small LRU keyed by sha1(text)+model avoids the redundant HTTP calls to
// Ollama/LM Studio's embed endpoint (~5-20ms each).
const _embedCache = new Map(); // key → Float32Array / number[]
const EMBED_CACHE_MAX = 256;

function _embedKey(text, model) {
  return createHash('sha1').update(`${model}\0${text}`).digest('hex');
}

export async function embed(text, { purpose = 'document' } = {}) {
  const { embedUrl, embedModel, embedProvider } = getCortexConfig();
  const key = _embedKey(text ?? '', `${embedProvider}:${embedModel}:${purpose}`);
  const cached = _embedCache.get(key);
  if (cached) {
    _embedCache.delete(key);
    _embedCache.set(key, cached);
    return cached;
  }

  const zero = () => new Array(VECTOR_DIM).fill(0);

  if (embedProvider === 'builtin') {
    try {
      const vec = await builtinEmbed(text ?? '', { purpose });
      if (vec.length && !vec.every(v => v === 0)) {
        _embedCache.set(key, vec);
        if (_embedCache.size > EMBED_CACHE_MAX) {
          const firstKey = _embedCache.keys().next().value;
          _embedCache.delete(firstKey);
        }
      }
      return vec;
    } catch (e) {
      console.warn('[cortex] Built-in embedding failed:', e.message);
      return zero();
    }
  }

  const spec = getProviderSpec(embedProvider);
  if (!spec || !spec.supportsEmbed) {
    console.warn('[cortex] Embed provider', embedProvider, 'not supported / has no embeddings endpoint.');
    return zero();
  }

  try {
    let url, body;
    if (spec.apiStyle === 'ollama') {
      url  = embedUrl || `${spec.baseUrl}/api/embeddings`;
      body = JSON.stringify({ model: embedModel, prompt: text });
    } else {
      // openai-compat (lmstudio, openai, deepseek, mistral, together, gemini, fireworks)
      url  = embedUrl || `${spec.baseUrl}/embeddings`;
      body = JSON.stringify({ model: embedModel, input: text });
    }
    const res = await fetch(url, {
      method: 'POST', headers: spec.headers, body,
      signal: AbortSignal.timeout(8000),
    });
    const data = await res.json();
    // Ollama: data.embedding  |  OpenAI-compat: data.data[0].embedding
    const vec = data.embedding ?? data.data?.[0]?.embedding ?? zero();
    const isZero = vec.length && vec.every(v => v === 0);
    if (!isZero) {
      _embedCache.set(key, vec);
      if (_embedCache.size > EMBED_CACHE_MAX) {
        const firstKey = _embedCache.keys().next().value;
        _embedCache.delete(firstKey);
      }
    } else if (data.error) {
      console.warn('[cortex] Embed API error:', data.error?.message ?? JSON.stringify(data.error));
    }
    return vec;
  } catch (e) {
    console.warn('[cortex] Embedding failed:', e.message);
    return new Array(VECTOR_DIM).fill(0);
  }
}

// ── Salience scoring ─────────────────────────────────────────────────────────
// Bare `Rate: "<text>"` matches training/train.py format_record('salience').
// Earlier we passed a verbose instruction including an Example tuple — the
// 135M cortex copied that tuple verbatim for every input regardless of
// content. Removing the instruction restored the head's actual learned
// discrimination.

export async function scoreSalience(text, meta = {}) {
  const safeText = text.slice(0, 300).replace(/"/g, "'");
  const raw = await generateCombined('', `Rate: "${safeText}"`, { caller: 'salience', ...meta });
  const s = safeParseJSON(raw);
  if (!s || typeof s.emotional_weight !== 'number') {
    return { emotional_weight: 0.5, decision_weight: 0.5, uniqueness: 0.5, composite: 0.5 };
  }
  return {
    emotional_weight: s.emotional_weight,
    decision_weight:  s.decision_weight,
    uniqueness:       s.uniqueness,
    composite: +(s.emotional_weight * 0.35 + s.decision_weight * 0.45 + s.uniqueness * 0.20).toFixed(3),
  };
}

// ── Contradiction detection ──────────────────────────────────────────────────
export async function checkContradiction(newText, existingMemories, meta = {}) {
  if (!existingMemories.length) return { contradicts: false };
  const safeNew = newText.slice(0, 300).replace(/"/g, "'");
  for (const existing of existingMemories.slice(0, 3)) {
    const safeEx = existing.text.slice(0, 300).replace(/"/g, "'");
    // Bare `A: "..." B: "..."` matches training/train.py format_record('contradiction').
    const raw = await generateCombined('', `A: "${safeNew}" B: "${safeEx}"`, { caller: 'contradiction', ...meta });
    const result = safeParseJSON(raw);
    if (result?.contradicts === true) {
      return { contradicts: true, conflicting_id: existing.id };
    }
  }
  return { contradicts: false };
}
